# ---------------------------------------------------------------- 532 event sourcing and CQRS
T.append(topic(532, 'event-sourcing-and-cqrs', R, 28, 'Event Sourcing and CQRS',
 ['Store state as an append-only log of events and rebuild it by replaying them',
  'Separate the write model from read models that projections keep up to date',
  'Judge when the extra moving parts pay for themselves'],
 3, 14, [238],
 [text(532, 1, 'State as a list of facts',
   "Instead of a row that holds an account’s current balance, store what happened to it: AccountOpened, Deposited ₹500, Withdrew ₹200. The current state is the result of applying the events in order. Events are immutable and named in the past tense; a mistake is corrected by a new event, such as a reversal, not by editing an old one. You get a full history for free and can answer questions like “what was the balance on 3 March?” by replaying up to that date.",
   ['event-log']),
  diagram(532, 2, 'Commands in, events out, views updated',
   'The write side decides; the read side catches up.', ['event-log', 'expected-version', 'projections'],
   ['A command arrives: “withdraw ₹200 from account 7”',
    'Load account 7 by replaying its events, or a snapshot plus the events after it',
    'Check the rule: the balance must stay at or above zero',
    'Append Withdrew ₹200 with expected version 42; reject if another write got there first',
    'Projections read the new event and update read tables such as balances and statements']),
  text(532, 3, 'Worked example: replay cost and snapshots',
   "An account with 20,000 events, at an estimated 5 µs to apply each one, takes 20,000 × 5 µs = 100 ms to load, on every command. Saving a snapshot of the state every 1,000 events caps the replay at the last 1,000 or fewer: at most 5 ms. A snapshot is only a cache. If it is lost or its format changes, delete it and rebuild it from the events, which remain the source of truth.",
   ['snapshots']),
  text(532, 4, 'CQRS: one model for decisions, others for reading',
   "Command Query Responsibility Segregation splits the code that changes state from the code that answers queries. The write side validates commands against the event stream; the read side keeps denormalised tables shaped for each screen, filled by projections that consume events. The cost is lag: just after a write, a read model may not show it yet. Return the new version from the command and let the screen wait for that version, or read from the write side for that one view. CQRS works without event sourcing, and the reverse is also true.",
   ['projections', 'read-lag']),
  text(532, 5, 'Trap: editing or reshaping stored events',
   "Stored events are a contract with every projection and with your own past. Renaming a field or changing what an event means breaks replay. Add a new event version and convert old shapes as they are read (upcasting) instead of rewriting history. Personal data needs a plan too: keep it out of events, or encrypt it with a per-person key that can be deleted when the person asks to be erased.",
   ['event-versioning'])],
 [mc('t532-a1', 'event-log', 'In an event-sourced account, a ₹500 deposit was recorded by mistake. How is it corrected?',
   [('a', 'Delete the Deposited event and replay'), ('b', 'Edit the event so its amount is zero'),
    ('c', 'Append a reversal event cancelling it'), ('d', 'Update the balance read table directly')], 'c',
   'a: deleting history breaks the audit trail and any projection that already used the event. b: editing an event rewrites a fact other systems may have acted on. c: correct, the log keeps both the mistake and its correction, and replay gives the right balance. d: the read table would disagree with the events and be overwritten on the next rebuild.'),
  mc('t532-a2', 'expected-version', 'Two withdrawals for the same account both load it at version 42 and try to append. What stops both succeeding when the balance covers only one?',
   [('a', 'Projections recompute the balance after both'), ('b', 'A snapshot that was taken at version 42'),
    ('c', 'An expected-version check on each append'), ('d', 'Ordering the two events by their timestamps')], 'c',
   'a: projections run after the fact; by then both withdrawals are recorded. b: a snapshot speeds up loading but does not guard writes. c: correct, the first append moves the stream to 43, so the second append, still expecting 42, is rejected and can reload and retry. d: timestamps order events but do not stop the second decision being made on stale state.'),
  mc('t532-a3', 'read-lag', 'A user withdraws money and the next screen, served from a projection, still shows the old balance. Why?',
   [('a', 'The projection has not processed the event yet'), ('b', 'The event was appended to the wrong stream'),
    ('c', 'Snapshots hide events that are newer than them'), ('d', 'The command was rejected without an error')], 'a',
   'a: correct, read models are updated asynchronously and lag the write side by a little. b: then the balance would stay wrong, not catch up a moment later. c: loading replays the events after a snapshot, so nothing is hidden. d: a rejected command returns an error; nothing would be written at all.'),
  mc('t532-a4', 'snapshots', 'What is a snapshot in an event-sourced system?',
   [('a', 'A cached state at a version, rebuildable from events'), ('b', 'A backup of the event store kept for disaster recovery'),
    ('c', 'The authoritative record that replaces older events'), ('d', 'A read model shaped to suit one screen')], 'a',
   'a: correct, it saves replay time and can be thrown away. b: backups protect the store itself; snapshots live alongside it to speed up loads. c: the events stay authoritative; deleting them would lose history. d: read models serve queries, while snapshots serve the write side.'),
  mc('t532-a5', 'es-fit', 'Which system gains most from event sourcing?',
   [('a', 'A profile page that stores a name and an avatar'), ('b', 'A product page cache rebuilt every hour'),
    ('c', 'A settings table read on every request'), ('d', 'A wallet where auditors ask how balances arose')], 'd',
   'a: simple overwrite-in-place data gains little from a history. b: a cache is derived data that can be recomputed from elsewhere. c: a settings table needs fast reads of the current value, not a history. d: correct, the event history is the explanation auditors ask for, and new reports can be built from it.'),
  order('t532-a6', 'projections', 'Order how a new read model is added to a live event-sourced system.',
   ['Write the projection that maps events to rows', 'Replay the full history into a new table',
    'Let it catch up with live events', 'Switch reads to the new table', 'Drop the old read model once unused'],
   ['s4', 's2', 's5', 's1', 's3'],
   'Because events hold the full history, a new view can be built beside the old one and swapped in only once it has caught up.'),
  est('t532-a7', 'snapshots', 'An account stream holds 50,000 events and applying one takes about 4 µs. Roughly how many milliseconds does a full replay take?', 'ms', 200,
   ['Events are applied one after another', 'Reading them is not counted'], '50,000 × 4 µs', '50,000 × 4 µs = 200,000 µs = 200 ms',
   'Design implication: 200 ms added to every command is too slow, so take a snapshot every 1,000 events and replay at most about 4 ms.', 0.15, [20, 2000])],
 flash(532, [('Event sourcing?', 'Store immutable events; current state is the result of replaying them.'),
             ('CQRS?', 'Separate the write model that decides from read models that projections keep updated.'),
             ('How are two writers kept from both appending?', 'An expected-version check: the append fails if the stream moved on.')]),
 src([('Martin Fowler: Event Sourcing', 'https://martinfowler.com/eaaDev/EventSourcing.html'),
      ('Martin Fowler: CQRS', 'https://martinfowler.com/bliki/CQRS.html'),
      ('Microsoft Learn: Event Sourcing pattern', 'https://learn.microsoft.com/en-us/azure/architecture/patterns/event-sourcing')]),
 deep(['event-log', 'expected-version', 'projections', 'read-lag', 'snapshots', 'event-versioning', 'es-fit'], 'How an event-sourced service handles a command',
  ["Each entity, such as an account or an order, has its own stream of events, identified by the entity id and numbered by version. The event store’s job is narrow: append events to a stream atomically and read a stream back in order. It is often a table keyed by (stream id, version) with a unique constraint, which makes the next step possible.",
   "A command is handled by loading the entity: read the latest snapshot if one exists, then apply the events after it. The handler checks business rules against that state, such as “balance must stay at or above zero”, and produces zero or more new events. It never changes the state directly; the new events are the change.",
   "The new events are appended with the version the handler loaded, here 42. If another command appended version 43 in between, the unique constraint or the store’s expected-version check rejects the write. The handler reloads and tries again, or reports a conflict. This is optimistic concurrency, and it is what keeps two decisions based on the same stale state from both being recorded.",
   "Projections subscribe to the events and maintain read models: a balance table, a statement list, a search index. Each projection records the last event position it processed, so it can resume after a crash, and it must be idempotent because events can be delivered again. Read models lag the write side, usually by milliseconds and by much longer after an outage, so screens that must show a fresh write need a version check or a read from the write side.",
   "Because the log is the source of truth, read models are disposable. A bug in a projection is fixed by correcting the code and replaying history into a new table; a new report is built the same way. The price is operational: event schemas must evolve compatibly, replays of large histories take time and capacity, and personal data in an immutable log needs a deliberate erasure strategy."],
  ['Domains where the history is the product: ledgers, orders, bookings and audit-heavy workflows.', 'Systems that need several differently shaped read models built from the same changes.'],
  ['Avoid it for simple create-read-update screens; a table with an audit log is far cheaper.', 'Avoid it when the team cannot run projections, replays and schema versioning in production.'],
  ['Approach', 'History kept', 'Complexity', 'Read freshness'],
  [['Plain table, updated in place', 'Current state only', 'Low', 'Immediate'],
   ['Table plus audit log', 'Changes, as a side record', 'Moderate', 'Immediate'],
   ['Event sourcing with CQRS', 'Full history is the source', 'High', 'Read models lag slightly']],
  'Catching up after a projection outage',
  ['500 events per second arrive steadily', 'The projection was down for 10 minutes', 'It can process 2,000 events per second'],
  ['Backlog: 500 × 600 s = 300,000 events.',
   'While catching up, new events keep arriving, so the backlog shrinks at 2,000 − 500 = 1,500 events per second.',
   'Time to catch up: 300,000 ÷ 1,500 = 200 s, a little over 3 minutes.',
   'During that time the read models show data up to 13 minutes old at worst.'],
  'A projection needs headroom well above the arrival rate, or every outage leaves a long period of stale screens. Alert on lag, not just on errors.',
  'A loan account as a stream of events', 'Illustrative example',
  "Illustrative: a lending app stores each loan as a stream: Disbursed, InstalmentDue, InstalmentPaid, LateFeeCharged, LateFeeWaived. When a customer disputes a late fee or an auditor asks how the outstanding amount on 5 January was computed, the team replays the stream up to that date and shows each step. A new collections dashboard was added later by writing one projection and replaying the full history into it, without touching the code that records payments.",
  [('“We will just fix the bad event in the database.”', '“I’d append a correcting event, so the history and every projection stay consistent.”'),
   ('“Reads are always up to date.”', '“Read models lag the write side, so I’d design the screens that need fresh data around that.”')],
  ['Events are immutable facts; state is a replay of them.', 'Appends use an expected version to stop conflicting writes.',
   'Projections build disposable read models that lag slightly.', 'Snapshots cap replay time; schemas must evolve compatibly.']),
 {"kind": "predict", "title": "A buggy projection", "prompt": "A loyalty-points projection gave double points for refunds for three weeks. The events themselves were recorded correctly. What is the cleanest fix?",
  "choices": [{"id": "a", "label": "Fix the projection and rebuild it from the events", "feedback": "Right: derived data is disposable, and replaying runs the corrected code over the true history."},
              {"id": "b", "label": "Append correcting events for each affected customer", "feedback": "The events were right; adding corrections would record facts that never happened."},
              {"id": "c", "label": "Patch the read table with a one-off script", "feedback": "Possible, but the script re-implements the logic by hand and can drift from the fixed projection."}],
  "correctId": "a",
  "reveal": "When the error is in derived data, fix the code that derives it and replay. Build the new read model beside the old one, switch reads over once it has caught up, then drop the old table."},
 see([(238, 'Publishing events alongside a state change is the dual-write problem this design avoids'),
      (44, 'The outbox and change data capture are lighter ways to publish changes from a normal table'),
      (72, 'Expected-version appends are optimistic locking applied to an event stream')])))

# ---------------------------------------------------------------- 533 multi-tenant backends
T.append(topic(533, 'multi-tenant-backends', R, 29, 'Multi-Tenant Backends: Isolation and Noisy Neighbours',
 ['Compare shared tables, a schema per tenant and a database per tenant',
  'Enforce the tenant boundary on every query, cache key and file path',
  'Stop one busy tenant from starving the others with per-tenant limits'],
 3, 14, [225],
 [text(533, 1, 'Three ways to share a database',
   "Pooled: every tenant’s rows sit in shared tables with a tenant_id column, the cheapest option per tenant and one migration for all. Schema per tenant: one database, a separate schema each, with better separation but a migration that runs thousands of times. Database per tenant (silo): strongest isolation, per-tenant backup and restore, and the highest cost. Many products mix them: small tenants pooled, large or regulated tenants given their own database.",
   ['tenancy-models']),
  text(533, 2, 'Worked example: one missing filter',
   "“SELECT * FROM invoices WHERE id = $1” looks harmless in a pooled table, until a user of tenant B sends tenant A’s invoice id. The fix has layers. Take the tenant id from the authenticated session, never from the request body. Include it in every query, ideally through composite keys like (tenant_id, id). Add database row-level security, such as a policy that only shows rows whose tenant_id matches a value set for the session, so a forgotten filter returns nothing instead of another customer’s data.",
   ['tenant-isolation']),
  diagram(533, 3, 'Where the tenant id comes from',
   'The tenant is decided once, on the server, and carried everywhere.', ['tenant-isolation', 'tenant-keys'],
   ['A request arrives with a session token',
    'The auth layer resolves the user’s tenant; a tenant id in the body is ignored',
    'The tenant id goes on the request context and the database session',
    'Each query filters by tenant, and row-level security rejects any that do not',
    'Cache keys, file paths, logs and metrics carry the tenant id too']),
  text(533, 4, 'Noisy neighbours and fair shares',
   "One tenant’s bulk export can take every worker and connection, and everyone else waits. Give each tenant a share: rate limits per tenant, a cap on concurrent jobs and connections, query timeouts, and fair scheduling so a queue serves tenants in turn instead of first come, first served. With a pool of 100 connections and a cap of 20 per tenant, the busiest tenant can never hold more than a fifth of it.",
   ['noisy-neighbour']),
  text(533, 5, 'Trap: cache keys without the tenant',
   "A cache entry keyed “report:2026-10” is filled by tenant A and then served to tenant B. The same leak happens with object storage paths, search indexes and temporary files. Put the tenant id in every key and path, filter search queries by it, and add a test that logs in as two tenants and checks neither can see the other’s data.",
   ['tenant-keys'])],
 [mc('t533-a1', 'tenancy-models', 'A product has 20,000 small tenants and 3 banks whose contracts require their data in a separate database. What fits?',
   [('a', 'A separate database for each of the 20,003 tenants'), ('b', 'Pool the small tenants; give each bank a database'),
    ('c', 'One schema per tenant inside a shared database'), ('d', 'Shared tables for all, with a bank flag per row')], 'b',
   'a: 20,003 databases to patch, migrate and back up is heavy for tenants that do not need it. b: correct, the cheap pooled model serves most tenants and the three banks get the isolation they pay for. c: a shared database does not meet a separate-database requirement, and 20,003 schemas are hard to migrate. d: a flag does not separate the data at all.'),
  mc('t533-a2', 'tenant-isolation', 'Where should the server get a request’s tenant id from?',
   [('a', 'A tenant_id field in the JSON body'), ('b', 'A subdomain, trusted as the client sent it'),
    ('c', 'The authenticated session, on the server'), ('d', 'A header the mobile app adds to requests')], 'c',
   'a: the body is attacker-controlled; anyone can type another tenant’s id. b: a subdomain can pick the tenant for routing, but it must still be checked against the session. c: correct, the server resolves it from who is logged in, so a user cannot claim another tenant. d: headers are just as easy to change as the body.'),
  mc('t533-a3', 'tenant-isolation', 'The code already filters every query by tenant. Why add row-level security in the database as well?',
   [('a', 'It catches a query that forgets the filter'), ('b', 'It makes the tenant queries run faster'),
    ('c', 'It replaces authenticating the user'), ('d', 'It lets tenants share cache entries safely')], 'a',
   'a: correct, it is a backstop: a missed filter returns no rows instead of another tenant’s rows. b: policies add a condition to queries; they do not speed them up. c: the database still needs to be told which tenant the session belongs to, which comes from authentication. d: caches sit outside the database and need their own tenant keys.'),
  mc('t533-a4', 'noisy-neighbour', 'One tenant’s bulk export fills the shared worker pool and other tenants’ jobs wait for minutes. Which fix targets the cause?',
   [('a', 'Double the number of workers for everyone'), ('b', 'Move all tenants to bigger database servers'),
    ('c', 'Retry the waiting jobs more often'), ('d', 'Cap each tenant’s concurrent jobs')], 'd',
   'a: the export grows to fill the extra workers too. b: the bottleneck is the shared worker pool, not the database. c: retries add load and do not reach the front of the queue sooner. d: correct, a per-tenant cap leaves room for everyone else however large one tenant’s export is.'),
  mc('t533-a5', 'tenant-keys', 'Tenant B sees tenant A’s monthly report on its dashboard. Which bug is most likely?',
   [('a', 'A cache key that leaves out the tenant id'), ('b', 'A replica lagging by a few seconds'),
    ('c', 'A missing index on the reports table'), ('d', 'A session token that expired mid-request')], 'a',
   'a: correct, two tenants mapped to the same key share the cached report. b: lag shows older data from the same tenant, not another tenant’s data. c: a missing index slows the query; it does not change which rows match. d: an expired token causes a login error, not someone else’s data.'),
  order('t533-a6', 'tenancy-models', 'Order the steps to move a large tenant from pooled tables to its own database.',
   ['Create the new database and run the migrations', 'Copy the tenant’s rows and start replicating its changes',
    'Pause the tenant’s writes briefly while replication catches up', 'Point the tenant’s routing entry at the new database',
    'Delete the tenant’s rows from the pool once checks pass'],
   ['s3', 's5', 's1', 's4', 's2'],
   'Copy and replicate first, so the pause is short; switch routing only when the copy is current; delete from the pool last, when the move is verified.'),
  est('t533-a7', 'noisy-neighbour', 'A pool has 100 database connections and each query holds one for 50 ms. A tenant is capped at 20 connections. At most how many queries per second can that tenant run?', 'queries/s', 400,
   ['Each connection runs one query at a time', 'Queries take 50 ms each'], '20 ÷ 0.05 s', '20 connections ÷ 0.05 s = 400 queries/s',
   'Sanity check: the other tenants keep at least 80 connections, about 1,600 queries per second, however hard that one tenant pushes.', 0.1, [2000, 20])],
 flash(533, [('Three tenancy models?', 'Shared tables with tenant_id, schema per tenant, database per tenant.'),
             ('Where does the tenant id come from?', 'The authenticated session on the server, never the request body.'),
             ('Noisy neighbour fix?', 'Per-tenant rate limits, concurrency caps, timeouts and fair scheduling.')]),
 src([('PostgreSQL: Row security policies', 'https://www.postgresql.org/docs/current/ddl-rowsecurity.html'),
      ('Microsoft Learn: Tenancy models for SaaS applications', 'https://learn.microsoft.com/en-us/azure/azure-sql/database/saas-tenancy-app-design-patterns'),
      ('OWASP: Multi-tenant security cheat sheet', 'https://cheatsheetseries.owasp.org/cheatsheets/Multi_Tenant_Security_Cheat_Sheet.html')]),
 deep(['tenancy-models', 'tenant-isolation', 'tenant-keys', 'noisy-neighbour'], 'How a request stays inside one tenant',
  ["The tenant is resolved once, at authentication. The session or token identifies a user, and the server looks up which tenant that user belongs to. A user in several tenants picks one, and the server checks the membership. A tenant id that arrives in a URL, header or body is at most a hint for routing, verified against the session, and never trusted on its own.",
   "The resolved tenant goes into the request context and from there into every data access. In pooled tables each query includes the tenant id, and keys are composite, (tenant_id, id), so even a lookup by id is scoped. The database session is told the tenant too, and a row-level security policy filters every query by it, so a forgotten condition returns nothing rather than another tenant’s rows.",
   "The same rule covers every other store. Cache keys start with the tenant id, object storage uses a per-tenant prefix with access checks, search queries carry a tenant filter, and background jobs carry the tenant id in their payload and set it again before touching data. Logs and metrics are tagged by tenant, which also makes it possible to see who is causing load.",
   "Shared capacity is divided on purpose. Each tenant gets a rate limit at the edge, a cap on concurrent jobs and database connections, and timeouts on expensive queries. Queues serve tenants in turn, or by weight for paid tiers, so a burst from one tenant waits behind its own work rather than everyone’s. Large tenants that still dominate can move to dedicated workers or their own database.",
   "The tenancy model can change per tenant. A routing table maps each tenant to its database or schema, so a tenant can move from the pool to a silo by copying its data, replicating changes, pausing writes briefly and switching its routing entry. Migrations then run on the pool once and on each silo, which is why most products keep the number of silos small."],
  ['Software sold to many organisations from one deployment.', 'Products where a few large customers need stronger isolation or their own backups.'],
  ['Avoid a database per tenant for thousands of small tenants; operations grow with the count.', 'Avoid relying on application filters alone for data that must never leak.'],
  ['Model', 'Isolation', 'Cost per tenant', 'Migrations'],
  [['Shared tables with tenant_id', 'Logical, by filters and policies', 'Lowest', 'Run once'],
   ['Schema per tenant', 'Separate tables per tenant', 'Moderate', 'Run once per schema'],
   ['Database per tenant', 'Separate database', 'Highest', 'Run once per database']],
  'Running one migration across many schemas',
  ['4,000 tenants, one schema each', 'The migration takes about 3 s per schema (an estimate)', 'Up to 8 run in parallel'],
  ['Run one after another: 4,000 × 3 s = 12,000 s, about 3.3 hours.',
   'With 8 in parallel: 12,000 ÷ 8 = 1,500 s, about 25 minutes.',
   'For those 25 minutes, some tenants are on the new schema and some on the old, so the code must work with both.',
   'In pooled tables the same change is one migration, though on a much larger table.'],
  'Per-tenant schemas multiply operational work. Budget for it, and keep code compatible with both versions while a migration rolls through.',
  'A billing product for small businesses and large firms', 'Illustrative example',
  "Illustrative: an Indian invoicing and tax-filing product serves thousands of small shops from pooled tables keyed by tenant id, with row-level security as a backstop. A few large enterprise customers ask for their data in a separate database in an Indian cloud region, with their own backups and the ability to restore only their data. The product routes those tenants to dedicated databases through a routing table, and caps every tenant’s concurrent exports so month-end filing by one large customer does not slow everyone else.",
  [('“The UI only shows the user’s own tenant, so we are safe.”', '“I’d enforce the tenant on the server and in the database, since requests can be crafted.”'),
   ('“A database per tenant is always the safest choice.”', '“It isolates best but multiplies operations; I’d pool small tenants and silo the ones that need it.”')],
  ['Pick a tenancy model per tenant size and contract; many products mix them.', 'Resolve the tenant from the session and enforce it in every query and key.',
   'Use row-level security as a backstop for forgotten filters.', 'Give each tenant a fair share with limits, caps and fair queues.']),
 {"kind": "tradeoff", "title": "Choosing a tenancy model", "prompt": "Pick the best fit for these constraints.",
  "setup": ['8,000 small tenants and 5 enterprise tenants', 'Enterprise contracts require separate backups and a restore of only their data', 'A small team runs operations'],
  "choices": [{"id": "a", "label": "Pooled tables for small tenants, a database each for the 5 enterprise ones", "feedback": "Right: the cheap model covers most tenants and only five databases need separate care."},
              {"id": "b", "label": "A schema per tenant for all 8,005 tenants", "feedback": "Isolates well, but every migration and check runs 8,005 times for a small team."},
              {"id": "c", "label": "Pooled tables for everyone, protected by row-level security", "feedback": "Cheapest to run, but restoring one enterprise tenant means picking its rows out of a shared backup."}],
  "correctId": "a",
  "reveal": "Mixed tenancy is common: pool the long tail for cost, and silo the few tenants whose contracts or size demand it. A routing table from tenant to database makes moving a tenant later a planned operation rather than a rewrite."},
 see([(306, 'A missing tenant filter is a broken access control bug, the top web risk'),
      (225, 'Authorisation decides what a user may do; tenancy decides whose data they can reach'),
      (233, 'Per-tenant rate limits are the first line of defence against noisy neighbours')])))

# ---------------------------------------------------------------- 534 tail latency in fan-out
T.append(topic(534, 'tail-latency-in-fan-out', R, 30, 'Tail Latency in Fan-out Requests',
 ['Work out how often a fan-out request waits on at least one slow backend',
  'Explain why the slowest call, not the average, sets the response time',
  'Cut the tail with hedged requests, per-call deadlines and partial results'],
 3, 13, [239],
 [text(534, 1, 'The slowest shard sets the pace',
   "A search query is sent to 100 index shards and the answer waits for all of them. If each shard is slower than its own p99 on 1% of calls, independently, the chance that at least one of the 100 is slow is 1 − 0.99^100 ≈ 63%. So most queries, including the median one, wait about as long as a shard’s p99. Fan-out turns a rare per-server delay into the normal case for the whole request.",
   ['fanout-tail']),
  text(534, 2, 'Worked example: the same 1% at fan-out 10, 50 and 100',
   "With a 1% slow rate per call: 10 calls give 1 − 0.99^10 ≈ 9.6% slow requests; 50 give about 39.5%; 100 give about 63.4%. Turning it around, to keep slow requests at 1% with 100 calls, each call may be slow only about 0.01% of the time, since 1 − 0.9999^100 ≈ 1%. That is why large fan-out systems care about each server’s p99.9 and p99.99, not its average.",
   ['fanout-tail']),
  diagram(534, 3, 'A hedged read',
   'Send a backup copy only when the first one is already slow.', ['hedging'],
   ['Send the read to replica A',
    'Wait as long as A’s p95 latency, say 20 ms',
    'Still no reply: send the same read to replica B',
    'Use whichever reply arrives first and cancel the other',
    'Only about 5% of reads are hedged, so the extra load is about 5%']),
  text(534, 4, 'Deadlines, partial answers and less fan-out',
   "Give each backend call its own deadline inside the request’s budget, and decide what to do when it passes. Search and feeds can return what 98 of 100 shards found and mark the result as partial. Reduce fan-out where you can: fewer, larger shards, or route a query only to the shards that can hold matches. Keep slow requests from queueing ahead of fast ones with separate pools for expensive work.",
   ['partial-results']),
  text(534, 5, 'Trap: hedging at once, or hedging writes',
   "Sending two copies of every request doubles load, and under heavy load that makes the tail worse, not better. Hedging a write that is not idempotent, such as a payment, can apply it twice. Hedge reads and idempotent calls, wait about the p95 before sending the second copy, cap hedges at a few percent of traffic, and cancel the loser so it stops using capacity.",
   ['hedging'])],
 [mc('t534-a1', 'fanout-tail', 'A page waits for 50 backend calls, each slow 1% of the time independently. About how often is the page slow?',
   [('a', 'About 1%'), ('b', 'About 5%'), ('c', 'About 40%'), ('d', 'About 50%')], 'c',
   'a: that is the per-call rate; the page waits for all 50. b: that is 5 calls’ worth, roughly 1 − 0.99^5. c: correct, 1 − 0.99^50 ≈ 39.5%. d: simply adding 50 × 1% overstates it, because some pages have several slow calls at once.'),
  mc('t534-a2', 'hedging', 'When should a hedged second request usually be sent?',
   [('a', 'At the same moment as the first request'), ('b', 'Only after the first request returns an error'),
    ('c', 'Once the first has taken about its p95 latency'), ('d', 'After the client’s full timeout has expired')], 'c',
   'a: hedging every request at once doubles the load. b: waiting for an error helps failures, not slow replies. c: correct, by then the first copy is in its slowest 5%, so a fresh copy probably finishes sooner, at about 5% extra load. d: by then the caller has given up and the hedge is useless.'),
  mc('t534-a3', 'hedging', 'Which call is unsafe to hedge without extra work?',
   [('a', 'A GET for a product page'), ('b', 'A search query across shards'),
    ('c', 'A POST that charges a card'), ('d', 'A read of one user’s settings')], 'c',
   'a: reads have no side effects, so a duplicate costs only capacity. b: a search is a read; duplicates are harmless. c: correct, two copies could charge twice unless the call carries an idempotency key. d: also a read.'),
  mc('t534-a4', 'partial-results', 'A search fans out to 100 shards with a 50 ms deadline each, and 2 shards miss it. What do many search systems do?',
   [('a', 'Fail the whole query with a 500 error'), ('b', 'Return the 98 shards’ results, marked partial'),
    ('c', 'Wait for the 2 shards with no deadline'), ('d', 'Retry all 100 shards from the start')], 'b',
   'a: failing loses 98% of good results over 2% missing. b: correct, a slightly incomplete answer on time is usually better for search and feeds. c: the query then takes as long as the slowest shard, which is the problem. d: retrying everything doubles load and still waits for the slow shards.'),
  mc('t534-a5', 'fanout-tail', 'Each request touches 100 shards. To keep slow requests near 1%, roughly how often may each shard be slow?',
   [('a', '1% of the time'), ('b', '0.5% of the time'), ('c', '0.1% of the time'), ('d', '0.01% of the time')], 'd',
   'a: that makes about 63% of requests slow. b: about 39% slow. c: about 9.5% slow. d: correct, 1 − 0.9999^100 ≈ 1%, so each shard needs a hundred times fewer slow calls than the target.'),
  order('t534-a6', 'hedging', 'Order the steps of a hedged read.',
   ['Send the read to one replica', 'Start a timer at that replica’s p95 latency', 'When the timer fires, send the same read to a second replica',
    'Take the first reply that arrives', 'Cancel the slower request'],
   ['s4', 's1', 's5', 's3', 's2'],
   'The timer is what keeps hedging cheap: only the slowest few percent of reads ever get a second copy.'),
  est('t534-a7', 'fanout-tail', 'A query fans out to 200 shards, each slower than its p99 on 1% of calls, independently. What percent of queries wait on at least one slow shard?', '%', 87,
   ['Shards are slow independently', '1% slow rate per shard'], '1 − 0.99^200', '0.99^200 ≈ 0.134, so about 87% of queries',
   'Design implication: at this fan-out a shard’s p99 is roughly the query’s median, so work on shard tails pays off far more than tuning averages.', 0.05, [1, 50])],
 flash(534, [('Chance a fan-out of n waits on a slow call?', '1 − (1 − p)^n; with p = 1% and n = 100 it is about 63%.'),
             ('Hedged request?', 'After about the p95 delay, send a second copy of a read; use the first reply and cancel the other.'),
             ('Two other tail cutters?', 'Per-call deadlines with partial results, and less fan-out per request.')]),
 src([('Google SRE book: Monitoring distributed systems', 'https://sre.google/sre-book/monitoring-distributed-systems/'),
      ('gRPC: Request hedging', 'https://grpc.io/docs/guides/request-hedging/')]),
 deep(['fanout-tail', 'hedging', 'partial-results'], 'Why fan-out amplifies the tail and how hedging trims it',
  ["A fan-out request sends one call to each of n backends, such as index shards, and waits for every reply. Its latency is the maximum of n latencies, not their average. If each backend is slow with probability p, independently, the request is slow with probability 1 − (1 − p)^n. With p = 1% and n = 100 that is about 63%, so the request’s median sits near the backends’ p99.",
   "Slow calls have ordinary causes: a garbage collection pause, a busy disk, a noisy neighbour on the same host, a queue behind one expensive request, a cache miss. They are mostly short and mostly independent between machines. That is what hedging exploits: the same request sent to a different replica a moment later will probably not hit the same bad luck.",
   "A hedged read sends the request to one replica, waits for a delay near that replica’s p95, and if no reply has arrived sends a copy to a second replica. Whichever answers first wins and the other is cancelled. Because only the slowest 5% of reads are hedged, the extra load is about 5%, while the slowest replies are replaced by a second, usually fast, attempt.",
   "Hedging needs safe calls and limits. The request must be a read or idempotent, the hedge rate must be capped, for example at a few percent of traffic, so it cannot double load during an incident, and cancellation must reach the server so the losing copy stops using capacity. When all replicas are slow because the whole service is overloaded, hedging cannot help and should back off.",
   "Other tools work alongside it. A per-call deadline, taken from the request’s total budget, bounds how long any one backend can hold the response; the caller can then return a partial answer and say so. Reducing fan-out, through fewer, larger shards or routing a query only to shards that can match, shrinks n directly. Separating expensive requests into their own pool stops them queueing in front of cheap ones."],
  ['Requests that wait on many backends: search, feeds, dashboards, scatter-gather queries.', 'Read paths where a p99 target matters more than a small increase in load.'],
  ['Avoid hedging writes or calls that are not idempotent.', 'Avoid hedging during overload; it adds load when there is none to spare.'],
  ['Technique', 'Cuts', 'Costs'],
  [['Hedged requests', 'Slow outliers on reads', 'A few percent extra load'],
   ['Per-call deadline with partial results', 'Waiting on stragglers', 'Answers may be incomplete'],
   ['Less fan-out per request', 'The chance of hitting a slow call', 'Re-sharding or smarter routing']],
  'What hedging costs and buys',
  ['10,000 reads per second', 'Hedge delay at the p95, about 20 ms', 'A second attempt is fast 95% of the time, independently'],
  ['Reads still waiting after 20 ms: 5% of 10,000 = 500 per second get a second copy.',
   'Extra load: 500 ÷ 10,000 = 5%, a little less once cancelled losers stop early.',
   'Without hedging, 5% of reads get no reply within 20 ms, and some of those take far longer.',
   'With hedging, a read is stuck only if the first copy passes 20 ms and the second is also in its slowest 5%: 5% × 5% = 0.25%. The rest finish in about 20 ms plus a normal reply.'],
  'Hedging is cheap when slowness is random and independent; it does nothing when every replica is slow for the same reason.',
  'A home screen built from many services', 'Illustrative example',
  "Illustrative: a food-delivery app’s home screen asks a dozen services for restaurants, offers, delivery estimates and recommendations. The team sets a 150 ms budget, gives each call its own deadline, and renders the screen without the recommendations block when that service misses it, marking the block to fill in later. Reads to the restaurant catalogue are hedged after their p95, while the order-placing call is never hedged and carries an idempotency key instead.",
  [('“Our servers have a 10 ms average, so pages are fast.”', '“With fan-out the page waits for the slowest call, so I’d look at the backends’ p99 and p99.9.”'),
   ('“Send every request twice and take the fastest.”', '“I’d hedge only after the p95 delay, cap the rate, and never hedge non-idempotent writes.”')],
  ['A fan-out request is as slow as its slowest call: 1 − (1 − p)^n.', 'At high fan-out, backend p99 becomes the request median.',
   'Hedge reads after the p95 delay, capped and cancelled.', 'Deadlines with partial results and less fan-out also trim the tail.']),
 {"kind": "predict", "title": "Hedging every request", "prompt": "A service sends every read to two replicas at once and uses the first reply. During a traffic spike, all replicas are at 90% CPU. What happens to its p99 latency?",
  "choices": [{"id": "a", "label": "It rises, because the copies add load to busy replicas", "feedback": "Right: doubled traffic deepens the queues on every replica, so both copies are slow."},
              {"id": "b", "label": "It falls, because one of the two copies is always fast", "feedback": "Only when slowness is random; under overload every replica is slow for the same reason."},
              {"id": "c", "label": "It stays the same, because the extra copy is cancelled", "feedback": "Cancelling happens after the winner replies; the loser has already queued and used capacity."}],
  "correctId": "a",
  "reveal": "Hedging helps when slowness is random and capacity is spare. Wait for the p95 before hedging, cap hedges at a few percent of traffic, and turn them off when the service is overloaded."},
 see([(239, 'Per-call deadlines come from the request’s total budget passed down the chain'),
      (229, 'Percentiles, not averages, are what reveal a fan-out tail problem'),
      (53, 'Timeouts, retries and circuit breakers are the other half of handling slow dependencies')])))

# ---------------------------------------------------------------- 535 long-running operations
T.append(topic(535, 'long-running-operations-in-apis', R, 31, 'Long-Running Operations in APIs',
 ['Accept slow work with 202 Accepted and a status resource the client can poll',
  'Keep polling cheap and retries safe with Retry-After, callbacks and idempotency keys',
  'Support cancellation, failure states and expiry of operations and their results'],
 2, 12, [227],
 [text(535, 1, 'Hand back a ticket, not a held connection',
   "Generating a 2 GB export can take four minutes. Holding the HTTP request open that long fails in ordinary ways: proxies and load balancers close idle connections (60 seconds is a common default), mobile networks drop, and every waiting request holds a server connection. Instead, accept the work, queue it and reply 202 Accepted with a Location header such as /operations/op_81. The client polls that URL until the operation finishes, then fetches the result.",
   ['async-202']),
  diagram(535, 2, 'Life of an operation',
   'The status resource is the record of where the work stands.', ['async-202', 'operation-states'],
   ['POST /exports with an Idempotency-Key; reply 202 and Location: /operations/op_81',
    'A worker picks it up: status moves from queued to running, with progress',
    'The client polls the status URL, waiting as long as Retry-After says',
    'Finished: status done with a link to the result, or failed with an error',
    'The operation and its result expire after a stated time, such as 7 days']),
  text(535, 3, 'Worked example: what polling costs',
   "50,000 exports a day, each running about 4 minutes. If clients poll every second, that is 240 polls each, or 12M status requests a day for 50,000 jobs. Polling every 10 seconds cuts it to 1.2M. Backing off instead (1, 2, 4, 8, 16 s, then every 30 s) needs only about a dozen polls per job, around 600,000 a day. Send Retry-After on each status reply so the server, not the client, sets the pace.",
   ['polling']),
  text(535, 4, 'Callbacks alongside the status URL',
   "A webhook on completion saves clients from polling at all, but webhooks get lost: the receiver is down, a firewall blocks it, or a retry gives up. Keep the status URL as the record and treat the callback as a hint that it is worth checking now. Sign callbacks so the receiver can tell they came from you, and include only the operation id, so a forged or replayed callback reveals nothing.",
   ['polling']),
  text(535, 5, 'Trap: a retried POST starts a second job',
   "The client’s POST times out before the 202 arrives, so it retries, and two exports run. Require an Idempotency-Key on the POST and return the same operation id for a repeat. Also plan for the unhappy endings: a cancel request moves the operation to cancelling and then cancelled, workers check for it between chunks, a worker that stops sending heartbeats gets its operation retried or marked failed, and done, failed and cancelled are final.",
   ['async-idempotency', 'operation-states'])],
 [mc('t535-a1', 'async-202', 'An endpoint starts a report that takes about 3 minutes to build. What should the first response be?',
   [('a', '200 OK, sent once the report finishes'), ('b', '202 Accepted with a status URL'),
    ('c', '201 Created with an empty report body'), ('d', '504 Gateway Timeout, asking for a retry')], 'b',
   'a: the connection must stay open for 3 minutes, and proxies may close it first. b: correct, the work is accepted and the client gets somewhere to check on it. c: 201 says the resource exists now, which it does not. d: a 504 tells the client something failed, and a retry would start the work again.'),
  mc('t535-a2', 'polling', 'How should a server tell clients how often to poll an operation’s status?',
   [('a', 'Close the connection when a client polls too soon'), ('b', 'Reply 429 to every poll until the work is done'),
    ('c', 'Document a fixed 1-second interval for all'), ('d', 'Send a Retry-After header on each status reply')], 'd',
   'a: closing connections looks like a network error and invites fast retries. b: 429 to well-behaved clients turns normal polling into errors. c: a fixed 1-second interval creates heavy load for long jobs. d: correct, the server can lengthen the wait for long jobs or under load.'),
  mc('t535-a3', 'operation-states', 'A status URL says “running” for hours because the worker crashed. What fixes this?',
   [('a', 'Clients poll more often so they notice sooner'), ('b', 'A heartbeat timeout that retries or marks it failed'),
    ('c', 'The status endpoint returns 500 while a job runs'), ('d', 'Status records are deleted after one hour')], 'b',
   'a: polling faster just reads the same stale status more often. b: correct, a worker that stops heartbeating has its operation retried or moved to failed, so clients get a final state. c: a 500 tells the client the status service broke, not the job. d: deleting the record leaves the client with a 404 and no explanation.'),
  mc('t535-a4', 'async-idempotency', 'A POST /exports times out before the 202 arrives, and the client retries with the same Idempotency-Key. What should happen?',
   [('a', 'A second export starts under a new id'), ('b', 'The server replies 409 with no id'),
    ('c', 'The server returns the same operation id'), ('d', 'The first export is cancelled and restarted')], 'c',
   'a: that is the duplicate the key exists to prevent. b: a 409 leaves the client unable to find the job it started. c: correct, the client gets the status URL of the export that is already running. d: restarting wastes the work already done.'),
  mc('t535-a5', 'polling', 'Why keep a status URL when you also send a completion webhook?',
   [('a', 'Webhooks cannot carry the result’s location'), ('b', 'Status URLs are needed to authenticate'),
    ('c', 'Clients must poll before a webhook is sent'), ('d', 'Webhooks can be lost; the URL is the record')], 'd',
   'a: a webhook can carry a link, but it may never arrive. b: authentication is separate from how status is reported. c: clients that get webhooks need not poll at all on the happy path. d: correct, a client that missed the callback can still find out the result.'),
  order('t535-a6', 'operation-states', 'Order a long-running export from the client’s side.',
   ['POST with an Idempotency-Key', 'Receive 202 and the status URL', 'Poll, waiting as long as Retry-After says',
    'See status done with a result link', 'Download the result before it expires'],
   ['s4', 's1', 's5', 's3', 's2'],
   'The key makes the first step safe to retry, and the expiry on the result is why the last step has a deadline.'),
  est('t535-a7', 'polling', '30,000 operations a day each run about 5 minutes, and clients poll every 2 seconds. Roughly how many status polls is that per day?', 'polls/day', 4500000,
   ['Each operation is polled from start to finish', '5 minutes is 300 seconds'], '30,000 × 300 ÷ 2', '150 polls each × 30,000 = 4.5M polls a day',
   'Design implication: a Retry-After of 30 s cuts this to 300,000 polls a day, and a completion webhook cuts it to almost none for clients that can receive one.', 0.1, [30000, 450000])],
 flash(535, [('First response to slow work?', '202 Accepted with a Location header pointing at a status resource.'),
             ('How is polling kept cheap?', 'Retry-After on each status reply, client backoff, and optional webhooks.'),
             ('Final states of an operation?', 'done (with a result link), failed (with an error) or cancelled.')]),
 src([('RFC 9110: 202 Accepted', 'https://www.rfc-editor.org/rfc/rfc9110#name-202-accepted'),
      ('RFC 9110: Retry-After', 'https://www.rfc-editor.org/rfc/rfc9110#name-retry-after'),
      ('Microsoft Learn: Asynchronous Request-Reply pattern', 'https://learn.microsoft.com/en-us/azure/architecture/patterns/async-request-reply')]),
 deep(['async-202', 'operation-states', 'polling', 'async-idempotency'], 'How an API runs work that outlasts a request',
  ["The client sends the request with an Idempotency-Key. The server validates it, checks the key and stores a new operation record, with an id, a status of queued, the request parameters and an expiry time, in the same transaction that enqueues the job. It replies 202 Accepted, a Location header pointing at /operations/{id}, and a small body with the id and status. If the key was seen before, it returns the existing operation instead.",
   "A worker takes the job, marks the operation running and updates progress as it goes, such as rows exported or a percentage. It sends heartbeats while it works. A supervisor looks for running operations whose heartbeat has stopped, then retries them if the work is idempotent or marks them failed with a reason, so no client polls a dead job forever.",
   "Clients poll the status URL. Each reply says the status and carries a Retry-After header, short at first and longer for jobs known to be slow or when the system is busy. Clients back off between polls and stop at a final state. Clients that can receive webhooks register a callback URL and get a signed notification on completion, but the status resource remains the record they can always check.",
   "The operation ends in one final state. done includes a link to the result, often a short-lived signed URL to a file in object storage. failed includes a machine-readable error code and a message. cancelled follows a cancel request: the API marks the operation cancelling, the worker checks for that between chunks, cleans up and marks it cancelled. A final state never changes again.",
   "Operations and results do not live forever. The API documents how long they are kept, for example 7 days, after which the status URL returns 404 or 410 and the result file is deleted. A cleanup job enforces this. The documented limit lets clients plan, and it stops storage from growing without bound as millions of old exports pile up."],
  ['Exports, reports, media processing and other work that takes more than a few seconds.', 'Requests whose duration varies widely and can exceed proxy timeouts.'],
  ['Avoid it for work that reliably finishes within about a second; a direct reply is simpler.', 'Avoid polling every second with no Retry-After; it creates load out of nothing.'],
  ['Pattern', 'Client effort', 'Server cost', 'When things go wrong'],
  [['Synchronous reply', 'None', 'A held connection per request', 'Timeouts lose the result'],
   ['202 plus polling', 'Poll and back off', 'Status reads', 'Client can always check status'],
   ['202 plus webhook', 'Receive callbacks', 'Delivery and retries', 'Lost callbacks need a fallback'],
   ['202, polling and webhook', 'Callback, with polling as backup', 'Both', 'Most robust']],
  'Held connections versus a ticket',
  ['1 export request arrives per second', 'Each export takes 240 s to build', 'The 202 reply takes about 50 ms'],
  ['Synchronous: by Little’s law, concurrent requests = arrival rate × time = 1 × 240 = 240 connections held open.',
   'Each held connection also needs a worker waiting on it, and any proxy with a 60 s idle timeout will cut them first.',
   'Asynchronous: 1 × 0.05 s = 0.05 connections busy on average for the requests themselves.',
   'The 240 builds still run, but on queue workers whose number you choose, not on request threads.'],
  'A ticket moves long work off the request path, where it no longer holds connections or depends on proxy timeouts.',
  'Bank statements and tax data exports', 'Illustrative example',
  "Illustrative: an accounting app lets a firm download twelve months of transactions for all its clients ahead of the tax filing deadline. The export can take several minutes and many firms ask in the same week. The API returns 202 with a status URL, sends Retry-After of 15 seconds and then longer, and notifies the firm’s webhook when the file is ready. The result link expires after seven days, and a retried request with the same idempotency key returns the export already running instead of starting another.",
  [('“We just raised the load balancer timeout to 10 minutes.”', '“I’d return 202 with a status URL, so long work does not depend on any proxy timeout.”'),
   ('“The webhook tells them when it is done.”', '“I’d keep a status URL as the record too, because callbacks can be lost.”')],
  ['Reply 202 with a status URL for work that outlasts a request.', 'Use Retry-After and backoff to keep polling cheap; add signed callbacks.',
   'Require an idempotency key so a retried POST does not start a second job.', 'Define final states, heartbeats, cancellation and expiry.']),
 {"kind": "predict", "title": "A slow PDF behind a load balancer", "prompt": "An endpoint builds PDFs synchronously. Most take 20 s, but large ones take 90 s. The load balancer closes connections idle for 60 s. What do users with large PDFs see?",
  "choices": [{"id": "a", "label": "A timeout error while the server keeps building the PDF", "feedback": "Right: the load balancer gives up at 60 s, but the work continues and its result has nowhere to go."},
              {"id": "b", "label": "The PDF, just after a longer wait", "feedback": "The connection is closed at 60 s, before the reply exists."},
              {"id": "c", "label": "A 202 response that the load balancer adds for them", "feedback": "Load balancers do not convert slow requests into asynchronous ones."}],
  "correctId": "a",
  "reveal": "The user gets an error, retries and starts a second 90-second build. Return 202 with a status URL, build in a worker, and the timeout stops mattering."},
 see([(227, 'The work behind a 202 runs as a background job on a queue'),
      (224, 'Idempotency keys make the starting POST safe to retry'),
      (237, 'Completion callbacks are webhooks and should be signed and retried the same way')])))

# ---------------------------------------------------------------- 536 testing a service
T.append(topic(536, 'testing-a-backend-service', R, 32, 'Testing a Service: Unit, Integration and Contract Tests',
 ['Match unit, integration, contract and end-to-end tests to the risks they catch',
  'Test data access against a real database instead of a mock that agrees with you',
  'Keep tests fast and repeatable by controlling time, randomness and shared state'],
 2, 13, [221],
 [text(536, 1, 'Match the test to the risk',
   "Unit tests check pure logic, such as a price or tax calculation, in milliseconds. Integration tests run your code against real dependencies, above all the database, and catch wrong SQL, missing migrations and violated constraints, in about a second each. Contract tests check that your API still gives each consumer the fields and types it relies on. End-to-end tests drive a whole user journey across services; they are slow and fail for unrelated reasons, so keep a few for the critical paths.",
   ['test-levels']),
  text(536, 2, 'Worked example: the bug a mock agreed with',
   "A sign-up handler relies on a unique constraint on email and turns the database’s unique-violation error into a 409. The unit test mocks the repository to “throw a duplicate error”, and passes. In production the driver reports the violation with a different error code from the one the handler checks, so users get a 500. Only a test against a real database, started fresh in a container and migrated with the real migrations, exercises the constraint and the actual error the driver returns.",
   ['real-dependencies']),
  diagram(536, 3, 'A consumer-driven contract test',
   'Each consumer states what it relies on; the provider checks it on every build.', ['contract-tests'],
   ['The consumer records the requests it sends and the response fields it reads',
    'Those expectations are published as a contract file',
    'The provider’s build replays each request against the real provider',
    'A removed field or changed type fails the provider’s build, before release',
    'Both sides deploy knowing they still agree']),
  text(536, 4, 'Flaky tests come from hidden inputs',
   "A test that sometimes fails usually reads something it does not control: the clock, random numbers, test order, data left by another test, or a real network call. Pass in a clock the test can set, seed random generators, give each test its own data (a rolled-back transaction or unique ids), and wait for a condition rather than a fixed sleep. Flakiness adds up: 400 tests that each fail 0.5% of the time make 1 − 0.995^400 ≈ 86% of runs go red.",
   ['flaky-tests']),
  text(536, 5, 'Trap: chasing coverage instead of risks',
   "90% line coverage can still miss the concurrent double booking, the migration that locks a table, the timeout path and the retried request. Coverage shows which lines ran, not whether the failure cases were checked. List the ways the service can fail, such as a dependency timeout, a duplicate request, a partial write or a bad input, and write a test for each one.",
   ['test-levels'])],
 [mc('t536-a1', 'test-levels', 'Which test best catches a wrong tax calculation for a cart?',
   [('a', 'An end-to-end test run through the browser'), ('b', 'A contract test against the payments API'),
    ('c', 'A unit test of the price function'), ('d', 'A load test at expected peak traffic')], 'c',
   'a: it could catch it, slowly, and a failure would not say which part was wrong. b: a contract checks the shape of calls between services, not the arithmetic. c: correct, pure logic is best tested directly with many cases, including rounding edges. d: load tests measure capacity, not correctness.'),
  mc('t536-a2', 'real-dependencies', 'A test with a mocked database passes, but production returns 500 on duplicate sign-ups. What would have caught it?',
   [('a', 'More unit tests around the mocked handler'), ('b', 'A higher line-coverage threshold in CI'),
    ('c', 'Running the same suite twice in a row'), ('d', 'An integration test on a real database')], 'd',
   'a: more tests against the same mock repeat the same wrong assumption. b: the lines already ran; coverage cannot see the wrong error mapping. c: a deterministic test passes twice just as easily. d: correct, a real database raises the real constraint error and exposes the mapping bug.'),
  mc('t536-a3', 'contract-tests', 'A provider team renames a JSON field. With consumer-driven contract tests, what fails first?',
   [('a', 'The provider’s own build'), ('b', 'The consumer’s production traffic'),
    ('c', 'The consumer’s unit tests'), ('d', 'A nightly end-to-end run')], 'a',
   'a: correct, the provider replays each consumer’s expectations and the missing field fails its build before release. b: that is what happens without contracts. c: the consumer’s tests use its own stub of the provider, which still has the old field. d: an end-to-end run might notice later, if it covers that field.'),
  mc('t536-a4', 'flaky-tests', 'A test checks that a token “expires in 1 hour” and fails a few times a week, always near midnight. What is the right fix?',
   [('a', 'Retry the test up to three times in CI'), ('b', 'Inject a clock the test can control'),
    ('c', 'Raise the test’s timeout to one hour'), ('d', 'Run the suite only during working hours')], 'b',
   'a: retries hide the flakiness and the bug it may point to. b: correct, the code reads time from a clock the test sets, so the result no longer depends on when it runs. c: the failure is about dates, not slowness. d: avoiding midnight hides a real date-boundary bug that users will hit.'),
  mc('t536-a5', 'flaky-tests', 'Tests pass one at a time but fail when the suite runs in random order. What is the likely cause?',
   [('a', 'The CI machine has too little memory'), ('b', 'A race inside the test framework itself'),
    ('c', 'Shared state left behind by another test'), ('d', 'The database is too slow under parallel load')], 'c',
   'a: memory pressure fails tests regardless of order. b: possible but rare; suspect your own tests first. c: correct, one test leaves data or settings that another depends on or trips over; isolate each test’s data. d: slowness causes timeouts, which do not depend on order.'),
  order('t536-a6', 'real-dependencies', 'Order the steps of an isolated database integration test.',
   ['Start a fresh database, for example in a container', 'Apply the real migrations', 'Begin a transaction for this test',
    'Run the code and check the rows it wrote', 'Roll back so the next test starts clean'],
   ['s3', 's5', 's1', 's4', 's2'],
   'Real migrations prove the schema, and the rollback gives every test the same starting point without rebuilding the database.'),
  est('t536-a7', 'flaky-tests', 'A suite has 300 tests and each fails at random 0.2% of the time, independently. Roughly what percent of runs fail at least once?', '%', 45,
   ['Failures are independent', 'No real bugs are present'], '1 − 0.998^300', '0.998^300 ≈ 0.55, so about 45% of runs',
   'Sanity check: nearly half the runs go red with no real bug, so people stop trusting the suite; each flaky test is worth fixing.', 0.1, [0.2, 60])],
 flash(536, [('What does an integration test catch that a unit test misses?', 'Wrong SQL, missing migrations and real constraint errors from the actual database.'),
             ('Consumer-driven contract?', 'Consumers publish what they rely on; the provider’s build checks it before release.'),
             ('Usual causes of flaky tests?', 'Time, randomness, test order, shared data and real network calls.')]),
 src([('Martin Fowler: The Practical Test Pyramid', 'https://martinfowler.com/articles/practical-test-pyramid.html'),
      ('Martin Fowler: Consumer-Driven Contracts', 'https://martinfowler.com/articles/consumerDrivenContracts.html'),
      ('Martin Fowler: Eradicating Non-Determinism in Tests', 'https://martinfowler.com/articles/nonDeterminism.html')]),
 deep(['test-levels', 'real-dependencies', 'contract-tests', 'flaky-tests'], 'How a backend test suite is put together',
  ["Start from risks, not layers. List what can go wrong: business rules computed wrongly, queries that return the wrong rows, a migration that breaks old data, an API change that breaks a consumer, a dependency that times out, a request that is retried. Each risk points at the cheapest kind of test that can catch it, and that kind is the one to write.",
   "Pure logic gets unit tests: functions that take values and return values, with no database or network. Keep business rules in such functions where you can, because they can then be tested with hundreds of cases, including rounding edges and empty inputs, in well under a second. Mocks belong at the boundary of this code, and only for things that are slow or outside your control.",
   "Data access gets integration tests against the real database engine, the same version as production, started fresh for the test run, often in a container, and built with the real migrations. Each test runs inside a transaction that is rolled back, or uses its own unique ids, so tests do not see each other’s data. These tests catch the bugs mocks cannot: SQL errors, constraint errors, wrong isolation assumptions and slow queries.",
   "Service boundaries get contract tests. Each consumer records the requests it makes and the parts of the response it reads; the provider’s pipeline replays them on every build. A provider can then remove a field nobody reads without fear, and is stopped from removing one that someone does. A small number of end-to-end tests cover the journeys that would cost the most to break, such as sign-up and checkout.",
   "Everything runs on every change, so speed and determinism matter. Time, randomness and identifiers are passed in so tests can fix them. Waits poll for a condition with a timeout instead of sleeping. Tests that turn out to be flaky are quarantined and fixed quickly, because a suite that fails at random teaches people to ignore red builds, and then real failures get ignored too."],
  ['Any service that will be changed by more than one person over time.', 'Services with consumers in other teams, where contracts prevent surprise breakage.'],
  ['Avoid mocking the database to test queries; the mock agrees with whatever you assumed.', 'Avoid a large end-to-end suite as the main safety net; it is slow and fails for unrelated reasons.'],
  ['Test kind', 'Catches', 'Speed', 'Main cost'],
  [['Unit', 'Logic errors', 'Milliseconds', 'Misses integration bugs'],
   ['Integration with a real database', 'SQL, migrations, constraints', 'Around a second each', 'Needs a database per run'],
   ['Contract', 'Breaking API changes', 'Seconds', 'Consumers must maintain contracts'],
   ['End-to-end', 'Whole-journey breaks', 'Tens of seconds each', 'Slow and flaky']],
  'A CI budget of 10 minutes',
  ['2,000 unit tests at about 5 ms each', '200 integration tests at about 300 ms each', '20 end-to-end tests at about 30 s each', '4 parallel CI workers'],
  ['Unit: 2,000 × 5 ms = 10 s.',
   'Integration: 200 × 0.3 s = 60 s.',
   'End-to-end: 20 × 30 s = 600 s, ten times the other two combined.',
   'Total 670 s, about 11 minutes on one worker; split over 4 workers, about 2.8 minutes.'],
  'End-to-end tests dominate the time even when there are few of them. Keep each one for a journey that really needs it, and push the rest down to integration and unit tests.',
  'A payments integration tested before go-live', 'Illustrative example',
  "Illustrative: a team adding UPI payments to an app tests its fee and refund arithmetic with unit tests, runs integration tests against a real database to check that a repeated payment callback is rejected by a unique constraint, and runs contract tests against the payment provider’s published sandbox behaviour. A handful of end-to-end tests cover pay, refund and a timed-out payment. The flakiest test turned out to depend on the time of day and was fixed by passing in a clock.",
  [('“We have 90% coverage, so it is well tested.”', '“Coverage shows which lines ran; I’d check that each failure mode, like timeouts and retries, has a test.”'),
   ('“We mock the database so tests are fast.”', '“I’d mock it in unit tests but run data access against a real database, since that is where the bugs are.”')],
  ['Pick the cheapest test that can catch each risk.', 'Test queries and migrations against a real database.',
   'Contract tests stop breaking API changes before release.', 'Control time, randomness and shared data to keep tests repeatable.']),
 {"kind": "tradeoff", "title": "A test plan for an orders service", "prompt": "Pick the best fit for these constraints.",
  "setup": ['The orders service owns a relational database schema', 'Three other teams call its API', 'CI must finish in under 10 minutes'],
  "choices": [{"id": "a", "label": "Unit tests, real-database integration tests and consumer contracts", "feedback": "Right: each risk is covered by the cheapest test that catches it, inside the time budget."},
              {"id": "b", "label": "A large end-to-end suite that runs all four services", "feedback": "Catches cross-service breaks, but it is slow, fails for unrelated reasons and will not fit 10 minutes."},
              {"id": "c", "label": "Unit tests with a mocked database, for speed", "feedback": "Fast, but SQL, migrations and constraints go untested, and API changes reach consumers unchecked."}],
  "correctId": "a",
  "reveal": "Logic in unit tests, data access against a real database, and contracts for the three consumers cover the main risks in a few minutes. Add a handful of end-to-end tests for the journeys that would cost most to break."},
 see([(323, 'These tests are the gates a CI/CD pipeline runs on every change'),
      (231, 'Contract tests are how you know an API change is still backward compatible'),
      (240, 'Schema compatibility checks are contract tests for messages and events')])))

# ---------------------------------------------------------------- 537 deleting data
T.append(topic(537, 'deleting-data-and-retention', R, 33, 'Deleting Data: Soft Deletes, Retention and Erasure',
 ['Choose between hard deletes, soft deletes and anonymisation for each kind of record',
  'Enforce retention periods with scheduled, batched purges or dropped partitions',
  'Erase a person’s data across replicas, caches, search indexes, logs and backups'],
 2, 13, [225],
 [text(537, 1, 'Soft delete, hard delete or anonymise',
   "A soft delete sets deleted_at and hides the row, so it can be undone, but every query must remember to filter it out, and a unique email blocks the person from signing up again; a partial unique index that covers only rows with deleted_at empty fixes that. A hard delete removes the row, which is simplest for privacy and hardest to undo. Anonymising keeps a record that must stay, such as an order for the accounts, but replaces the name, email and address.",
   ['delete-modes']),
  text(537, 2, 'Worked example: one erasure request, nine places',
   "A user asks to have their data erased. Their data sits in the main database tables, a read replica (which follows automatically), the cache, the search index, the analytics warehouse, object storage holding their uploads, application logs, outside processors such as the email provider, and the backups. A request that only deletes the users row leaves most of it behind. Keep a data map, a list of every system holding personal data and how to erase from each, and drive erasure from it.",
   ['erasure']),
  diagram(537, 3, 'A retention purge',
   'Old data is removed on a schedule, a little at a time, and the job proves it ran.', ['retention'],
   ['Policy: delete raw access logs after 90 days',
    'A daily job finds rows older than the cutoff using an indexed timestamp',
    'It deletes them in batches of 5,000, pausing between batches',
    'It records how many rows it deleted, for the audit trail',
    'An alert fires if the oldest remaining row is past the cutoff']),
  text(537, 4, 'Backups cannot be edited, so plan around them',
   "You cannot practically delete one person from last week’s backup. Two common answers: keep backups for a short, documented period and, after any restore, replay a log of erasures before the system goes live; or encrypt each person’s sensitive fields with their own key and delete the key on erasure, which makes every copy unreadable at once. That second approach is called crypto-shredding.",
   ['erasure', 'crypto-shredding']),
  text(537, 5, 'Trap: erasing records the law says to keep',
   "Some records must be kept for years even after a customer asks for erasure, such as invoices and payment records for tax and accounting law. Erasure then removes what is not required and anonymises or restricts what is. Write the retention period for each kind of data, with its reason, before building the delete button, and put legal holds on top for data under dispute or investigation.",
   ['delete-modes', 'retention'])],
 [mc('t537-a1', 'delete-modes', 'With soft deletes, a person who deleted their account cannot sign up again with the same email. Why?',
   [('a', 'The email is still cached in the session store'), ('b', 'Soft deletes keep the row locked until a purge'),
    ('c', 'The unique index still covers the deleted row'), ('d', 'The deleted_at column is missing an index')], 'c',
   'a: a session cache does not enforce uniqueness in the database. b: a soft delete is an ordinary update and holds no lasting lock. c: correct, the row still exists, so the unique email constraint blocks the new insert; a partial unique index on rows with deleted_at empty fixes it. d: a missing index slows queries but rejects nothing.'),
  mc('t537-a2', 'delete-modes', 'An order must be kept for the accounts, but the customer asked to be erased. What fits?',
   [('a', 'Hard-delete the order along with the customer'), ('b', 'Soft-delete the order so it is hidden'),
    ('c', 'Refuse the request until the records expire'), ('d', 'Anonymise the personal fields, keep the order')], 'd',
   'a: deleting records the law requires you to keep creates a different problem. b: a hidden row still holds all the personal data. c: the personal data that is not required can and should be removed now. d: correct, the accounting record stays and the name, email and address go.'),
  mc('t537-a3', 'crypto-shredding', 'How can a person’s data be made unreadable inside backups you cannot edit?',
   [('a', 'Mark the person as deleted in the next backup'), ('b', 'Compress the backups so the rows are unreadable'),
    ('c', 'Encrypt it with their own key, then delete the key'), ('d', 'Restore each backup to delete them, then re-save it')], 'c',
   'a: older backups still contain the data. b: compression is reversible by anyone. c: correct, without the key every copy of the ciphertext, including in backups, is unreadable. d: possible in principle, but restoring and rewriting every backup for each request is slow, risky and rarely done.'),
  mc('t537-a4', 'retention', 'A purge deletes 40 million expired rows in one statement at midday. What is the main risk?',
   [('a', 'Long locks, a huge transaction and replica lag'), ('b', 'The rows return after the next vacuum'),
    ('c', 'The table’s indexes are dropped'), ('d', 'Backups stop including the table')], 'a',
   'a: correct, one giant delete holds locks, fills the log and makes replicas fall behind, at the busiest time of day. b: vacuum reclaims space from deleted rows; it does not bring them back. c: deleting rows leaves indexes in place. d: backups include the table whatever its size.'),
  mc('t537-a5', 'erasure', 'After a user is erased from the main database, their name still shows up in search results. What was missed?',
   [('a', 'Rebuilding the users table’s primary key'), ('b', 'Removing their documents from the search index'),
    ('c', 'Running a vacuum on the users table'), ('d', 'Rotating the database user’s password')], 'b',
   'a: the primary key has nothing to do with the copy held by search. b: correct, the search index is a separate copy that must be erased too, which is why a data map lists it. c: vacuum reclaims space inside the database only. d: credentials do not change what data is stored.'),
  order('t537-a6', 'erasure', 'Order the handling of an erasure request.',
   ['Verify the requester’s identity', 'Look up every system holding their data in the data map', 'Delete or anonymise in each system',
    'Record what was erased, without keeping the erased data', 'Confirm completion to the person'],
   ['s2', 's4', 's1', 's5', 's3'],
   'Verify first so an attacker cannot erase someone else; the record proves the work was done without keeping what was erased.'),
  est('t537-a7', 'retention', 'A log table gains 30M rows a day. The daily purge deletes 5,000 rows per batch, and each batch takes 0.2 s including its pause. How many minutes does one day’s purge take?', 'minutes', 20,
   ['The purge removes one day of rows', 'Batch time is steady'], '30M ÷ 5,000 × 0.2 s ÷ 60', '6,000 batches × 0.2 s = 1,200 s = 20 minutes',
   'Sanity check: 20 minutes a day is fine, but if batches slow to 2 s each the purge takes over 3 hours, so alert on its duration.', 0.1, [2, 200])],
 flash(537, [('Soft delete pitfalls?', 'Every query must filter deleted rows, and unique constraints still see them.'),
             ('Crypto-shredding?', 'Encrypt a person’s data with their own key; deleting the key erases every copy.'),
             ('Fast way to drop old time-based data?', 'Partition by day or month and drop whole partitions past retention.')]),
 src([('PostgreSQL: Partial indexes', 'https://www.postgresql.org/docs/current/indexes-partial.html'),
      ('PostgreSQL: Table partitioning', 'https://www.postgresql.org/docs/current/ddl-partitioning.html'),
      ('OWASP: User Privacy Protection cheat sheet', 'https://cheatsheetseries.owasp.org/cheatsheets/User_Privacy_Protection_Cheat_Sheet.html')]),
 deep(['delete-modes', 'retention', 'erasure', 'crypto-shredding'], 'How data leaves a system on purpose',
  ["Every kind of record gets a retention rule before it is built: what it is, why it is kept, for how long, and what happens at the end, whether delete, anonymise or archive. Access logs might be kept 90 days, sessions 30 days, invoices for as long as tax law requires. The rule turns “delete old data some day” into a job with a cutoff that can be checked.",
   "Expiry is enforced by scheduled jobs, not by hand. A purge job selects rows older than the cutoff through an indexed timestamp and deletes them in small batches with pauses, so it never holds long locks or floods replicas. For high-volume, time-ordered data, partition the table by day or month and drop whole partitions past the cutoff, which takes moments instead of hours and leaves no dead rows behind.",
   "User-initiated deletion picks a mode per table. Records that support needs to restore for a while are soft-deleted with deleted_at and hard-deleted or anonymised after a grace period. Records that must be kept for legal reasons are anonymised: personal fields are replaced, and the business facts, such as the amount and the date, stay. Queries read through views or default filters that exclude soft-deleted rows.",
   "Erasure must reach every copy. The data map lists each system holding personal data: main tables, caches, search indexes, the analytics warehouse, object storage, logs, queues and outside processors. The erasure workflow calls each one and records completion. Logs are the hardest, so the better fix is upstream: avoid writing personal data into logs in the first place, or log pseudonymous ids instead.",
   "Backups are handled by policy rather than editing. Keep them for a documented, limited time; when one is restored, replay the erasure log before opening the system to users. For data that must disappear everywhere at once, encrypt it with a per-person key held in a key store and delete the key on erasure. The ciphertext left in backups, replicas and old files is then unreadable."],
  ['Any system holding personal data, logs or records with a legal retention period.', 'Products that offer users a delete-my-account option.'],
  ['Avoid soft deletes as the only mechanism for personal data; hidden is not erased.', 'Avoid one huge DELETE for expiry; batch it or drop partitions.'],
  ['Mode', 'Recoverable', 'Privacy', 'Main cost'],
  [['Soft delete', 'Yes, until purged', 'Data still stored', 'Filters on every query'],
   ['Hard delete', 'Only from backups', 'Strong', 'No undo'],
   ['Anonymise', 'Business facts only', 'Strong, if done fully', 'Must find every personal field'],
   ['Crypto-shred', 'No', 'Covers backups and copies', 'Key management per person']],
  'How retention sets storage',
  ['30M log rows a day', 'About 200 bytes per row, indexes included', 'Retention of 90 days versus 365 days'],
  ['Per day: 30M × 200 bytes = 6 GB.',
   'At 90 days: 6 GB × 90 = 540 GB.',
   'At 365 days: 6 GB × 365 ≈ 2.2 TB, about four times as much.',
   'With daily partitions, expiry is one dropped partition a day instead of 30M row deletes.'],
  'The retention period is a storage and privacy decision at the same time. Shorter retention means less to store, less to secure and less to erase.',
  'The Digital Personal Data Protection Act, simplified', 'Public law, simplified',
  "India’s Digital Personal Data Protection Act, 2023 gives people the right to ask for their personal data to be erased, and expects organisations to erase personal data once the purpose it was collected for is served, unless another law requires it to be kept. Tax and accounting laws can require invoices and payment records to be kept for years. A product therefore anonymises what it must keep and erases the rest. This summary is simplified; the detailed rules decide specifics, so check them with counsel.",
  [('“We soft-delete the user, so they are deleted.”', '“The data is still stored; I’d hard-delete or anonymise after a grace period and erase every copy.”'),
   ('“We will just delete old rows with one query.”', '“I’d batch the purge or drop partitions so it does not lock tables or lag replicas.”')],
  ['Set a retention rule per kind of data before building it.', 'Purge in batches or by dropping partitions.',
   'Soft delete is reversible but not erasure; anonymise what must be kept.', 'Erase every copy, and use short backup retention or crypto-shredding.']),
 {"kind": "tradeoff", "title": "Account deletion with an undo window", "prompt": "Pick the best fit for these constraints.",
  "setup": ['Users can delete their accounts', 'Support wants 30 days to undo deletions made by mistake', 'The privacy policy promises erasure within 30 days'],
  "choices": [{"id": "a", "label": "Soft delete now, then erase or anonymise on day 30", "feedback": "Right: support can undo within the window, and the promise is kept when it ends."},
              {"id": "b", "label": "Hard delete everything at once", "feedback": "Keeps the privacy promise but leaves support nothing to restore."},
              {"id": "c", "label": "Soft delete and keep the rows indefinitely", "feedback": "Undo works, but the erasure promise is broken and the hidden data still needs protecting."}],
  "correctId": "a",
  "reveal": "A grace period followed by real erasure meets both needs. Drive the final step from a scheduled job and the data map, so the cache, search index and other copies are erased too, and record that it ran."},
 see([(330, 'Backup retention decides how long erased data lingers in old copies'),
      (236, 'Purges walk large tables in key order, the same way keyset pagination does'),
      (229, 'Keeping personal data out of logs makes erasure far easier')])))

# ---------------------------------------------------------------- 538 batch jobs over millions of rows
T.append(topic(538, 'batch-jobs-over-large-tables', R, 34, 'Batch Jobs Over Millions of Rows: Chunking, Checkpoints and Throttling',
 ['Process a large table in key-ordered chunks with a saved checkpoint',
  'Make each chunk idempotent so a crashed job can resume safely',
  'Throttle batch work so live traffic and replicas keep up'],
 3, 13, [236],
 [text(538, 1, 'One giant transaction does not scale',
   "Backfilling a new column on 50M rows with a single UPDATE holds locks for a long time, writes one enormous transaction to the log, makes replicas fall far behind, and if it fails at 90% it rolls back everything and starts again. The same job run as thousands of small transactions keeps each lock brief, lets replicas keep pace, and turns a failure into losing one chunk instead of hours of work.",
   ['chunking']),
  diagram(538, 2, 'Key-ordered chunks with a checkpoint',
   'Each pass picks up exactly where the last one stopped.', ['chunking', 'checkpoints'],
   ['Read the checkpoint: last id done = 1,240,000',
    'Select the next 2,000 rows WHERE id > 1,240,000 ORDER BY id',
    'Process them and write the results in one short transaction',
    'Save the chunk’s last id as the new checkpoint in that same transaction',
    'Pause if replica lag or live latency is over its limit, then repeat']),
  text(538, 3, 'Worked example: how long a backfill takes',
   "50M rows in chunks of 2,000 is 25,000 chunks. At 150 ms per chunk that is 3,750 s, about an hour; adding a 100 ms pause between chunks makes it 25,000 × 0.25 s = 6,250 s, about 1.7 hours. Selecting chunks with OFFSET instead would make each chunk skip all earlier rows: chunk 20,000 reads past 40M rows before returning 2,000. Key-ordered chunks start from the index every time, so the last chunk costs the same as the first.",
   ['chunking']),
  text(538, 4, 'Idempotent chunks make restarts dull',
   "A job can crash after writing a chunk but before saving its checkpoint, unless both happen in one transaction, and then that chunk runs again. Make the work safe to repeat: set values computed from the row (SET total = price × qty) rather than adding to them, add a condition such as WHERE total IS NULL, and use upserts with unique keys. For side effects such as sending emails, record a per-row sent marker in the same transaction as the work.",
   ['checkpoints', 'batch-idempotency']),
  text(538, 5, 'Trap: running flat out against the primary',
   "A backfill running at full speed can take the primary database’s disk and CPU, so live p99 latency rises and replicas fall behind, which users see as their own changes disappearing for a while. Throttle it: a fixed rate, pauses whenever replica lag passes a limit such as 1 second, backing off when live latency rises, and running in quieter hours. A job that takes a day without anyone noticing beats one that takes an hour and pages the on-call engineer.",
   ['throttling'])],
 [mc('t538-a1', 'chunking', 'Why run a 50M-row backfill in chunks of a few thousand rows?',
   [('a', 'Chunked updates use less disk in total'), ('b', 'Short transactions keep locks and lag small'),
    ('c', 'Chunks let the job skip rows it does not need'), ('d', 'Smaller chunks reduce the total work done')], 'b',
   'a: the total data written is about the same. b: correct, each transaction is brief, replicas keep up, and a failure loses only one chunk. c: which rows are touched depends on the WHERE clause, not the chunking. d: chunking adds a little overhead; its value is safety, not less work.'),
  mc('t538-a2', 'chunking', 'Why select each chunk with WHERE id > last_id rather than OFFSET?',
   [('a', 'OFFSET returns rows in a random order'), ('b', 'OFFSET cannot be combined with ORDER BY'),
    ('c', 'Each chunk starts from the index, not by skipping'), ('d', 'Keyset queries take no locks of any kind')], 'c',
   'a: with ORDER BY, OFFSET is ordered too; its cost is the problem. b: OFFSET is normally used with ORDER BY. c: correct, a keyset query seeks straight to the next key, while OFFSET reads and discards every earlier row, so late chunks get slower and slower. d: the writes in each chunk still take row locks.'),
  mc('t538-a3', 'checkpoints', 'A job commits each chunk, then saves its checkpoint in a separate transaction, and crashes between the two. What happens on restart?',
   [('a', 'The last chunk is skipped'), ('b', 'The last chunk is processed again'),
    ('c', 'The whole job restarts from row one'), ('d', 'The database rolls back both writes')], 'b',
   'a: the checkpoint still points before the chunk, so nothing is skipped. b: correct, the work is redone, which is safe only if the chunk is idempotent; saving the checkpoint in the same transaction avoids it. c: the checkpoint is only one chunk behind. d: the chunk’s transaction had already committed.'),
  mc('t538-a4', 'batch-idempotency', 'Which chunk update is safe to run twice?',
   [('a', 'SET total = total + price × qty'), ('b', 'SET visits = visits + 1'),
    ('c', 'INSERT a copy of each row into an archive with no key'), ('d', 'SET total = price × qty')], 'd',
   'a: running it twice adds the amount twice. b: every rerun increments again. c: without a unique key, a rerun inserts duplicates. d: correct, it sets the value from the row itself, so a second run writes the same result.'),
  mc('t538-a5', 'throttling', 'During a backfill, replica lag climbs to 40 s and users stop seeing their own changes. What should the job do?',
   [('a', 'Pause until lag is under a limit, then resume'), ('b', 'Use bigger chunks to finish sooner'),
    ('c', 'Switch to one large transaction'), ('d', 'Keep going; the lag clears when it ends')], 'a',
   'a: correct, lag-aware throttling lets replicas catch up and keeps the job running safely. b: bigger chunks make each transaction heavier and lag worse. c: one huge transaction is the worst case for replicas. d: users suffer for the whole run, which may be hours.'),
  order('t538-a6', 'checkpoints', 'Order one pass of a resumable batch job.',
   ['Read the last saved checkpoint', 'Fetch the next chunk after it, in key order', 'Write the results in a short transaction',
    'Save the chunk’s last key as the checkpoint', 'Check replica lag and pause if needed'],
   ['s3', 's5', 's1', 's4', 's2'],
   'The checkpoint brackets the work: read it first, advance it only after the chunk is written, then let the throttle decide when the next pass starts.'),
  est('t538-a7', 'chunking', 'A job updates 12M rows in chunks of 4,000, and each chunk takes 0.3 s including its pause. About how many minutes does it run?', 'minutes', 15,
   ['Chunk time stays steady', 'No restarts'], '12M ÷ 4,000 × 0.3 s ÷ 60', '3,000 chunks × 0.3 s = 900 s = 15 minutes',
   'Sanity check: with OFFSET-based chunks the late chunks would scan millions of skipped rows each, and the same job could take many hours.', 0.1, [1.5, 150])],
 flash(538, [('Why chunk a backfill?', 'Short transactions keep locks, log size and replica lag small, and failures cheap.'),
             ('Keyset chunk query?', 'WHERE id > last_id ORDER BY id LIMIT n, so every chunk starts from the index.'),
             ('How is a batch kept from hurting live traffic?', 'Throttle on replica lag and live latency, with pauses and a rate limit.')]),
 src([('PostgreSQL: Populating a database', 'https://www.postgresql.org/docs/current/populate.html'),
      ('PostgreSQL: Monitoring replication (pg_stat_replication)', 'https://www.postgresql.org/docs/current/monitoring-stats.html'),
      ('Google SRE workbook: Data processing pipelines', 'https://sre.google/workbook/data-processing/')]),
 deep(['chunking', 'checkpoints', 'batch-idempotency', 'throttling'], 'How a resumable batch job walks a big table',
  ["The job walks the table in primary-key order, or in any indexed, unique order. Each pass selects the next n rows after the last key it finished, with a condition such as WHERE id > :last ORDER BY id LIMIT 2000. Because the database seeks straight to that key in the index, every chunk costs about the same, whether it is the first or the twenty-thousandth.",
   "Each chunk is processed and written in one short transaction. The chunk size is chosen so a transaction takes well under a second, typically a few hundred to a few thousand rows, and tuned by measuring. Small enough to keep locks brief and replicas close behind; large enough that per-transaction overhead does not dominate.",
   "The checkpoint, the last key finished, is saved in a small job table, ideally in the same transaction as the chunk’s writes, so the two can never disagree. On restart the job reads the checkpoint and continues. If the checkpoint is saved separately, a crash can repeat one chunk, so the chunk’s work must be idempotent anyway: set values rather than increment them, filter for rows not yet done, and upsert on unique keys.",
   "Between chunks the job checks the health of the system it is loading: replica lag, the primary’s CPU or I/O, and the p99 latency of live queries. If any is over its limit, it sleeps and checks again. A rate cap, a time-of-day window and a kill switch that stops it within one chunk give operators control without killing processes.",
   "The job reports progress: the checkpoint, rows done, rows per second and an estimated finish time. It ends with a verification step, such as counting rows still not done, which must be zero. For schema changes the usual order is to add the new column, deploy code that writes it for new rows, backfill old rows with the job, verify, and only then make the column required or start reading from it."],
  ['Backfills, data migrations, re-encryption, recomputing derived columns.', 'Any job touching more rows than one transaction should hold.'],
  ['Avoid OFFSET to page through a big table; late pages get slower and slower.', 'Avoid running batch work flat out on the primary during peak hours.'],
  ['Approach', 'Cost per chunk', 'Restart', 'Impact on live traffic'],
  [['One big UPDATE', 'One huge transaction', 'From the start', 'Long locks and replica lag'],
   ['OFFSET chunks', 'Grows with position', 'From a page number', 'Rising load as it goes'],
   ['Keyset chunks with checkpoint and throttle', 'Flat', 'From the last key', 'Bounded by the throttle']],
  'OFFSET versus keyset over a large table',
  ['50M rows', 'Chunks of 2,000, so 25,000 chunks', 'OFFSET reads and discards every earlier row'],
  ['Keyset: each chunk reads about 2,000 rows, so about 50M row reads in total.',
   'OFFSET: chunk k first skips (k − 1) × 2,000 rows; on average about 25M skipped rows per chunk.',
   'Total for OFFSET: about 25,000 × 25M ≈ 6 × 10^11 row reads, roughly 12,500 times the keyset total.',
   'Even at millions of rows read per second, that is days of extra work.'],
  'Key-ordered chunks keep a long job’s cost linear in the table size; OFFSET makes it quadratic.',
  'Backfilling a column in a large payments table', 'Illustrative example',
  "Illustrative: a payments company adds a normalised merchant category to a table of several hundred million transactions. The team adds a nullable column, deploys code that fills it for new rows, then runs a backfill in chunks of 2,000 by primary key, saving the checkpoint with each chunk and pausing whenever replica lag passes one second. The job runs for most of a day at a rate nobody notices. A final count of rows still null confirms it finished before the column is made required.",
  [('“We will run one UPDATE over the weekend.”', '“I’d chunk it by key with a checkpoint, so it can pause, resume and never lag the replicas.”'),
   ('“If it crashes we will rerun it.”', '“I’d make each chunk idempotent, so reruns are safe and it resumes from the checkpoint.”')],
  ['Walk big tables in key order, in short transactions.', 'Save a checkpoint with each chunk so the job resumes, not restarts.',
   'Make chunk work idempotent: set rather than increment.', 'Throttle on replica lag and live latency.']),
 {"kind": "tradeoff", "title": "Backfilling 80M rows on a live database", "prompt": "Pick the best fit for these constraints.",
  "setup": ['80M rows on the primary database need a new column filled', 'Users read from replicas and expect their changes within 2 s', 'The job may take a day'],
  "choices": [{"id": "a", "label": "Keyset chunks with a checkpoint, paused when replica lag passes 1 s", "feedback": "Right: steady, resumable progress that never lets replicas fall behind what users notice."},
              {"id": "b", "label": "A single UPDATE statement run in a quiet hour", "feedback": "One 80M-row transaction causes heavy lag even when quiet, and a late failure rolls back everything."},
              {"id": "c", "label": "Many parallel workers at full speed, to finish quickly", "feedback": "Finishes sooner but floods the primary’s I/O, and replicas fall well behind the 2 s promise."}],
  "correctId": "a",
  "reveal": "When the job may take a day, use the day. Throttling on replica lag keeps the user-visible promise, checkpoints make restarts cheap, and key-ordered chunks keep every chunk equally fast."},
 see([(236, 'Keyset chunks are keyset pagination applied to a job instead of a screen'),
      (272, 'A backfill is the middle step of an expand-and-contract schema change'),
      (356, 'Throttling a batch job is backpressure applied to your own work'),
      (227, 'Long backfills usually run as background jobs with retries and progress')])))

# ---------------------------------------------------------------- 539 audit trails
T.append(topic(539, 'audit-trails-in-a-service', R, 35, 'Audit Trails: Recording Who Did What',
 ['Decide which actions need an audit record and what each record must hold',
  'Write audit records atomically with the change they describe, append-only',
  'Make tampering evident with hash chains and narrow write permissions'],
 2, 12, [225],
 [text(539, 1, 'Audit logs are not debug logs',
   "Debug logs are for engineers: sampled, rotated within days, and allowed to drop lines under load. An audit trail is for security, support and compliance: a complete record of every privileged or sensitive action, kept for months or years and searchable by person and by record. Each entry says who acted (and on whose behalf), what they did to which record, when by server time, from where (IP address, request id), why if a reason was given, and whether it was allowed or denied.",
   ['audit-scope']),
  diagram(539, 2, 'Writing an audit record with the change',
   'The record and the change commit together, then move to a separate store.', ['audit-atomic'],
   ['A support agent issues a ₹2,000 refund on order 81',
    'One transaction updates the order and inserts the audit row',
    'Audit row: actor, action refund.issue, target order 81, amount, reason, request id',
    'A relay copies committed audit rows to a separate append-only store',
    'Investigators search by actor, target or time range']),
  text(539, 3, 'Worked example: the refund nobody can explain',
   "A refund handler commits the refund and then sends an audit event to a logging service. The process crashes between the two, and the refund has no record. In the reverse order, the audit event is sent, the refund’s transaction then fails, and the trail shows a refund that never happened. Writing the audit row in the same database transaction removes both cases. Record denied attempts too: 30 refused refund attempts from one account in a minute is exactly what an investigator wants to find.",
   ['audit-atomic']),
  text(539, 4, 'Tamper evidence: hash chains and narrow permissions',
   "An attacker or insider who can edit the trail can hide what they did. Store with each record a hash of the previous record’s hash plus its own content; changing or deleting any record breaks every hash after it, and a verifier finds the break. Copy the latest hash somewhere the same people cannot write. Give the application’s database role permission to insert and read audit rows, never to update or delete them.",
   ['tamper-evidence']),
  text(539, 5, 'Trap: secrets and personal data inside audit records',
   "A before-and-after diff of a user record can capture password hashes, tokens, card numbers or full addresses, and an audit store kept for years then becomes a prize for attackers and a problem for erasure requests. Record which fields changed, mask sensitive values, and refer to people by id so their details can be erased elsewhere while the trail stays intact.",
   ['audit-scope'])],
 [mc('t539-a1', 'audit-scope', 'Which event most needs an audit record?',
   [('a', 'A user views their own order list'), ('b', 'The service retries a slow database query'),
    ('c', 'An admin makes a user an account owner'), ('d', 'A worker finishes a thumbnail job')], 'c',
   'a: reading one’s own data is normal use; debug logs or metrics are enough. b: retries belong in operational logs and metrics. c: correct, a privilege change by an admin is exactly what security and auditors will ask about. d: routine background work is an operational event, not a privileged action.'),
  mc('t539-a2', 'audit-atomic', 'Why write the audit row in the same transaction as the change it describes?',
   [('a', 'So the audit queries run faster'), ('b', 'So the record exists exactly when the change does'),
    ('c', 'So the record gets a database timestamp'), ('d', 'So the change can be undone from the record')], 'b',
   'a: where the row is written does not make searches faster. b: correct, a crash can no longer leave a change without a record or a record without a change. c: a timestamp can be set either way. d: undoing a change is a separate, deliberate action with its own record.'),
  mc('t539-a3', 'tamper-evidence', 'Each audit record stores a hash of the previous record’s hash plus its own content. What does this give you?',
   [('a', 'Records can no longer be read by attackers'), ('b', 'Old records can be deleted to save space'),
    ('c', 'Editing any old record breaks every later hash'), ('d', 'The audit store no longer needs backups')], 'c',
   'a: hashing is not encryption; the records stay readable. b: deleting records breaks the chain, which is the point. c: correct, a verifier recomputing the chain finds where it was altered. d: a chain shows tampering but cannot bring back lost data.'),
  mc('t539-a4', 'audit-scope', 'A support agent signs in as a customer to debug an issue and changes the customer’s address. Who should the record show as the actor?',
   [('a', 'The customer, as it was their session'), ('b', 'The agent, acting on behalf of the customer'),
    ('c', 'The support tool’s service account'), ('d', 'Nobody, as it was only debugging')], 'b',
   'a: the customer did not make the change, and a dispute would blame the wrong person. b: correct, record the real actor and the account they acted for. c: a shared service account hides which person acted. d: changes made while debugging are still changes to a customer’s data.'),
  mc('t539-a5', 'tamper-evidence', 'Which database permissions fit the application’s role on the audit table?',
   [('a', 'All privileges, for flexibility'), ('b', 'UPDATE and DELETE, for corrections'),
    ('c', 'Owner of the table, to manage it'), ('d', 'INSERT and SELECT only')], 'd',
   'a: full privileges let a compromised application rewrite history. b: corrections are new records, not edits. c: an owner can alter or drop the table. d: correct, the application can add and read records but cannot change or remove them.'),
  order('t539-a6', 'audit-atomic', 'Order the handling of a refund that must be audited.',
   ['Check the agent may refund this amount', 'Begin a transaction', 'Update the order and insert the audit row',
    'Commit', 'Relay the audit row to the append-only store'],
   ['s3', 's5', 's1', 's4', 's2'],
   'Authorise first, so a denied attempt is recorded as denied; commit the change and its record together; copy to the separate store only after commit.'),
  est('t539-a7', 'audit-scope', 'A service records 2M audit events a day at about 1 KB each and keeps them for 7 years. Roughly how many terabytes is that?', 'TB', 5.1,
   ['No compression', 'Replicas not counted'], '2M × 1 KB × 365 × 7', '2 GB a day × 2,555 days ≈ 5,110 GB ≈ 5.1 TB',
   'Sanity check: about 5 TB before replicas belongs in cheap append-only storage indexed by actor, target and time, not in the main database’s hot tables.', 0.1, [0.7, 51])],
 flash(539, [('Fields of an audit record?', 'Who (and on whose behalf), what, which target, when, from where, why, and the outcome.'),
             ('Why write it in the same transaction?', 'So the record exists exactly when the change commits.'),
             ('Hash chain?', 'Each record hashes the previous hash plus its content, so edits break every later hash.')]),
 src([('OWASP: Logging cheat sheet', 'https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html'),
      ('NIST SP 800-92: Guide to Computer Security Log Management', 'https://csrc.nist.gov/pubs/sp/800/92/final'),
      ('PostgreSQL: GRANT', 'https://www.postgresql.org/docs/current/sql-grant.html')]),
 deep(['audit-scope', 'audit-atomic', 'tamper-evidence'], 'How a service keeps a trustworthy audit trail',
  ["Start with a list of auditable actions, agreed with security, support and whoever handles compliance: sign-ins and failed sign-ins, permission and role changes, exports of personal data, refunds and other money movements, configuration changes, and any action taken by staff on a customer’s account. Each gets a stable action name, such as role.grant or refund.issue, so records can be searched and counted.",
   "Each record has a fixed shape. The actor is a person or service id, plus the account they acted on behalf of when staff impersonate a customer. The action and target type and id say what happened to what. Server time, request id and source address place it. A reason or ticket number explains it when one is required, and the outcome says whether it was allowed or denied, with the rule that denied it.",
   "The record is written in the same database transaction as the change, usually into an audit table, so the two commit or roll back together. Denied attempts are written in their own small transaction, because the main change never happens. A relay, the same outbox pattern used for events, then copies committed rows to a separate append-only store that the application cannot modify.",
   "Tampering is made evident rather than assumed impossible. Each record includes the hash of the previous record’s hash plus its own content, and a scheduled job recomputes the chain and alerts on a break. The latest hash is copied periodically to a place with different administrators. Database permissions let the application insert and read audit rows only; retention and deletion are handled by a separate, itself audited, process.",
   "Records are useful only if people can search them. Index by actor, target and time; give support and security a search screen with its own access controls; and report regularly on unusual patterns, such as staff exporting many customers’ data or a spike in denied attempts. Keep personal details out of the records themselves, referencing people by id, so the trail can outlive erasure of the underlying data."],
  ['Admin panels, support tools, money movements and access to personal data.', 'Any system where someone may later ask who changed what, and when.'],
  ['Avoid treating debug logs as the audit trail; they are sampled, rotated and editable.', 'Avoid storing secrets or full personal data in audit records.'],
  ['Approach', 'Atomic with change', 'Tamper evidence', 'Main cost'],
  [['Lines in application logs', 'No', 'None', 'Gaps and short retention'],
   ['Separate audit call after commit', 'No, a crash loses records', 'Depends on the store', 'Network call per action'],
   ['Audit row in the transaction, relayed to an append-only store', 'Yes', 'Hash chain and narrow permissions', 'Extra table and relay']],
  'Verifying a hash chain',
  ['2M audit records a day', 'About 2 µs to hash a 1 KB record (an estimate)', 'One verifier process'],
  ['One day: 2M × 2 µs = 4 s to recompute the chain.',
   'One year: about 730M records × 2 µs ≈ 1,460 s, about 25 minutes.',
   'Daily verification of the new records is cheap; a full re-verification fits in a maintenance job.',
   'Each daily checkpoint hash stored elsewhere lets a verifier start from that point instead of the beginning.'],
  'Tamper evidence costs seconds a day to check. The expensive part is storing years of records, which is why they move to cheap append-only storage.',
  'A support panel at a lending company', 'Illustrative example',
  "Illustrative: support staff at a lending app can waive late fees and update a borrower’s bank details. Each action writes an audit row in the same transaction, naming the agent, the borrower’s account, the fee or field changed and the ticket number. When a borrower disputes a change months later, or an internal review asks why one agent waived fees on many accounts in a week, the team searches the trail by agent and date and shows each step, without the trail ever holding the full bank account number.",
  [('“We log everything, so we have an audit trail.”', '“Debug logs are sampled and rotated; I’d write audit rows with the change and keep them append-only.”'),
   ('“Nobody can edit the audit table.”', '“I’d make edits evident with a hash chain and give the application insert-only rights.”')],
  ['Audit privileged and sensitive actions with a fixed record shape.', 'Write the record in the same transaction as the change.',
   'Make tampering evident with hash chains and insert-only permissions.', 'Keep secrets and personal details out of the records.']),
 {"kind": "predict", "title": "Auditing after the commit", "prompt": "A refund handler commits the refund, then calls a separate audit service over the network. The audit service is down for 5 minutes and the calls fail silently. What does the trail show for those minutes?",
  "choices": [{"id": "a", "label": "No record of the refunds made in those minutes", "feedback": "Right: the refunds committed, and the only copy of the audit event was a failed network call."},
              {"id": "b", "label": "The refunds, written late once the service returns", "feedback": "Only if the events were stored durably and retried; failed calls are simply gone."},
              {"id": "c", "label": "Nothing, because the refunds were rolled back", "feedback": "The refunds had already committed before the audit call was made."}],
  "correctId": "a",
  "reveal": "Write the audit row in the same transaction as the refund and relay it afterwards. Then an outage of the audit store delays the copy but never loses a record."},
 see([(229, 'Debug logs and metrics serve engineers; audit trails serve investigators'),
      (225, 'Authorisation decisions, including denials, are what an audit trail records'),
      (238, 'Relaying audit rows after commit is the outbox pattern again')])))

# ---------------------------------------------------------------- 540 holding many live connections
T.append(topic(540, 'holding-many-live-connections', R, 36, 'Holding Many Live Connections on the Server',
 ['Estimate the memory and file descriptors that many long-lived connections need',
  'Deliver a message to a user connected to another server through pub/sub',
  'Survive deploys and outages without a reconnect storm or lost messages'],
 3, 13, [356],
 [text(540, 1, 'A connection is a resource you hold',
   "Each open WebSocket or server-sent events stream holds a file descriptor, kernel socket buffers and some application state for as long as the user stays connected. At an estimated 20 KB per connection, 100,000 connections need about 2 GB on one server. Raise the per-process file-descriptor limit (a soft limit of 1,024 is a common default), and use event-driven I/O so one thread serves many sockets instead of a thread per connection.",
   ['connection-cost']),
  diagram(540, 2, 'Reaching a user on another server',
   'Gateways hold the sockets; a pub/sub layer connects them.', ['cross-node-fanout'],
   ['User A is connected to gateway 3, user B to gateway 7',
    'A’s message reaches the chat service through gateway 3',
    'The service publishes it to B’s channel in a pub/sub system',
    'Gateway 7, subscribed to B’s channel, writes it down B’s connection',
    'If B is offline, it waits in storage until B reconnects and asks for it']),
  text(540, 3, 'Worked example: a reconnect storm',
   "A gateway holding 200,000 connections restarts. If every client reconnects within about a second, the fleet faces 200,000 TLS handshakes and authentications at once. Against an estimated capacity of 10,000 a second, that is a 20 s backlog; clients time out and retry, adding still more. If clients instead wait a random delay spread over 60 s before reconnecting, the load is about 3,300 a second, well within capacity.",
   ['reconnect-storm']),
  text(540, 4, 'Heartbeats and graceful drains',
   "Load balancers and home routers silently drop connections that look idle, and the server gets no close event. Send a ping every 30 s or so and close the connection if two in a row go unanswered. For deploys, drain instead of killing: take the gateway out of the load balancer, send connected clients a reconnect message that tells each to wait a random delay, give them a few minutes to move, then close what remains and stop.",
   ['heartbeats', 'draining']),
  text(540, 5, 'Trap: treating the socket as the delivery guarantee',
   "A message written to a socket can still be lost if the connection dies before the client reads it. Give each message a per-conversation sequence number and store it before sending. The client remembers the last number it processed and, on reconnecting, asks for everything after it; the server replays from storage. Live delivery is the fast path, and the replay on reconnect is what makes delivery reliable.",
   ['resume'])],
 [mc('t540-a1', 'connection-cost', 'A gateway holds 250,000 connections at about 16 KB each. Roughly how much memory do the connections use?',
   [('a', 'About 400 MB'), ('b', 'About 4 GB'), ('c', 'About 16 GB'), ('d', 'About 40 GB')], 'b',
   'a: that is ten times too small. b: correct, 250,000 × 16 KB = 4,000,000 KB, about 4 GB. c: that would be 64 KB each. d: ten times too large.'),
  mc('t540-a2', 'cross-node-fanout', 'User B is connected to a different server from user A. How does A’s message reach B?',
   [('a', 'A’s server opens a socket to B’s device'), ('b', 'B’s client polls A’s server every second'),
    ('c', 'B’s server receives it through pub/sub'), ('d', 'The load balancer copies it to every server')], 'c',
   'a: devices accept no inbound connections; they connect out to gateways. b: B does not know which server A uses, and polling every second defeats the open connection. c: correct, B’s gateway subscribes to B’s channel and pushes what is published there. d: load balancers route requests; they do not broadcast messages to servers.'),
  mc('t540-a3', 'reconnect-storm', 'After a gateway restart, every dropped client reconnects at once and the replacement gateway falls over. What prevents this?',
   [('a', 'Longer heartbeat intervals on the server'), ('b', 'Reconnecting at once to another gateway'),
    ('c', 'A higher file-descriptor limit'), ('d', 'A random, growing delay before reconnects')], 'd',
   'a: heartbeats detect dead connections; they do not spread out reconnects. b: moving the whole crowd to another gateway moves the overload with it. c: the bottleneck is handshakes per second, not open descriptors. d: correct, jittered backoff spreads the reconnects over time so the fleet absorbs them.'),
  mc('t540-a4', 'heartbeats', 'Idle connections die after a few minutes with no close event on the server. What is the usual fix?',
   [('a', 'Raise the server’s read timeout to an hour'), ('b', 'Have every client reconnect each minute'),
    ('c', 'Ping every 30 s; close if pongs stop'), ('d', 'Switch from server-sent events to polling')], 'c',
   'a: the middlebox drops the idle connection regardless of the server’s timeout. b: constant reconnects add handshake load for no reason. c: correct, regular pings keep the path active and reveal dead connections so the server can free them. d: polling avoids idle sockets but gives up the push model and adds request load.'),
  mc('t540-a5', 'resume', 'A phone loses signal for 20 s during a chat. How does it get the messages it missed?',
   [('a', 'It reconnects and asks for all after its last id'), ('b', 'The server resends everything since login'),
    ('c', 'The socket holds them until signal returns'), ('d', 'It does not; chats show only live messages')], 'a',
   'a: correct, sequence numbers let the client ask for exactly the gap, which the server replays from storage. b: resending everything wastes bandwidth and duplicates what was already shown. c: the old connection is dead; its buffers are gone. d: users expect to see what was sent while they were away.'),
  order('t540-a6', 'draining', 'Order a graceful deploy of one connection gateway.',
   ['Stop sending it new connections at the load balancer', 'Send connected clients a reconnect hint with a random delay',
    'Wait a few minutes while clients move', 'Close the connections that remain', 'Stop the process and start the new version'],
   ['s4', 's2', 's5', 's1', 's3'],
   'Draining moves clients over minutes, at a pace the other gateways can absorb, instead of dropping them all at once.'),
  est('t540-a7', 'reconnect-storm', '200,000 dropped clients reconnect with jitter, spread evenly over 50 s. About how many handshakes per second must the fleet absorb?', 'handshakes/s', 4000,
   ['Reconnects are spread evenly', 'Each client reconnects once'], '200,000 ÷ 50 s', '200,000 ÷ 50 = 4,000 handshakes/s',
   'Sanity check: with no jitter all 200,000 arrive within about a second, fifty times this rate.', 0.1, [200000, 40000])],
 flash(540, [('Cost of a live connection?', 'A file descriptor, socket buffers and app state, held for as long as it is open.'),
             ('Reaching a user on another gateway?', 'Publish to the user’s channel; the gateway holding their socket subscribes and pushes.'),
             ('Avoiding a reconnect storm?', 'Jittered, growing reconnect delays, and draining gateways gradually on deploy.')]),
 src([('RFC 6455: The WebSocket Protocol', 'https://www.rfc-editor.org/rfc/rfc6455'),
      ('MDN: Using server-sent events', 'https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events'),
      ('man7.org: epoll(7)', 'https://man7.org/linux/man-pages/man7/epoll.7.html')]),
 deep(['connection-cost', 'cross-node-fanout', 'reconnect-storm', 'heartbeats', 'draining', 'resume'], 'How a gateway fleet holds connections and delivers messages',
  ["Clients open a long-lived connection to a gateway: a WebSocket for two-way traffic or a server-sent events stream for server-to-client updates. The gateway authenticates the connection once, records which user it belongs to, and keeps it open. Gateways do little else, so they can be scaled and restarted separately from the services that hold the business logic.",
   "Each gateway serves many sockets from a few threads with event-driven I/O, such as epoll on Linux, which tells the process which sockets are ready instead of parking a thread on each. Its capacity is set by memory per connection, the file-descriptor limit, CPU for heartbeats and messages, and above all how many new handshakes it can complete per second.",
   "When a service wants to reach a user, it does not need to know which gateway holds them. It publishes to the user’s channel in a pub/sub system, and the gateway holding that user subscribes to the channel while the connection is open. Messages are also written to storage with a sequence number before publishing, so a client that was away can catch up.",
   "Connections fail all the time: phones change networks, routers drop idle flows, gateways restart. Heartbeats find dead connections so their resources are freed. Clients reconnect with exponential backoff and random jitter, and on reconnecting they send the last sequence number they processed, so the server replays only the gap. Delivery is at least once, so clients ignore duplicates by sequence number.",
   "Deploys and incidents are where fleets break. A gateway being replaced is drained: removed from the load balancer, its clients told to reconnect after a random delay, then closed after a few minutes. Capacity is planned for the reconnect rate after losing a whole gateway, not only for the steady number of connections, and admission control sheds handshakes beyond what the fleet can complete."],
  ['Chat, live scores, notifications, collaborative editing and dashboards that push updates.', 'Any feature where users stay connected for minutes or hours.'],
  ['Avoid a thread per connection; memory and scheduling fall over long before sockets do.', 'Avoid relying on the open socket alone for delivery; store and replay by sequence number.'],
  ['Concern', 'Usual limit', 'Mitigation'],
  [['Memory per connection', 'RAM per gateway', 'Lean per-connection state, more gateways'],
   ['New handshakes per second', 'TLS and auth CPU', 'Jittered reconnects, gradual drains'],
   ['Cross-gateway delivery', 'Pub/sub throughput', 'Channels per user or room, sharded pub/sub']],
  'Sizing a gateway',
  ['A 32 GB gateway, keeping half its RAM free for headroom', 'About 16 KB per connection (an estimate)', 'About 5,000 new handshakes per second per gateway (an estimate)'],
  ['Memory: 16 GB ÷ 16 KB ≈ 1,000,000 connections.',
   'If that gateway dies, its clients must reconnect elsewhere. Spread over 60 s, that is about 16,700 handshakes per second.',
   'At about 5,000 handshakes per second per gateway, absorbing it takes about 3.3 gateways’ worth of spare handshake capacity.',
   'So a fleet often holds far fewer connections per gateway than memory allows, such as 200,000, to keep failures absorbable.'],
  'Memory says how many connections a gateway can hold; the reconnect rate after a failure says how many it should hold.',
  'Live scores during a big match', 'Illustrative example',
  "Illustrative: a sports app pushes ball-by-ball updates to millions of fans during a cricket final. Each fan’s app holds a connection to a gateway subscribed to the match channel. When a wicket falls, many more users open the app at once, so the team pre-scales gateways before the match, uses jittered reconnects, and drains gateways slowly if one must be replaced mid-match. Updates carry sequence numbers, so an app that dropped off in a tunnel fetches exactly the balls it missed.",
  [('“WebSockets scale to millions; we will just open them.”', '“Each one costs memory and a descriptor, and a failed gateway causes a reconnect storm, so I’d size for that.”'),
   ('“If we wrote it to the socket, the user got it.”', '“The connection can die first, so I’d store messages with sequence numbers and replay the gap on reconnect.”')],
  ['Each live connection holds memory and a file descriptor.', 'Pub/sub lets any service reach a user on any gateway.',
   'Jittered reconnects and gradual drains prevent reconnect storms.', 'Sequence numbers and replay on reconnect make delivery reliable.']),
 {"kind": "predict", "title": "Ten gateways, no pub/sub", "prompt": "A chat service runs 10 gateways and users are assigned to them at random. Each gateway delivers a message only if the recipient is connected to that same gateway. What do users see?",
  "choices": [{"id": "a", "label": "Only about 1 message in 10 arrives live", "feedback": "Right: sender and recipient share a gateway only about a tenth of the time."},
              {"id": "b", "label": "Every message arrives, a little more slowly", "feedback": "Nothing carries messages between gateways, so most never reach the recipient’s socket."},
              {"id": "c", "label": "Every message arrives twice", "feedback": "Duplicates come from retries, not from missing cross-gateway delivery."}],
  "correctId": "a",
  "reveal": "Connections are spread over many servers, so delivery needs a layer that finds the right one: pub/sub channels per user or room, or a lookup of which gateway holds each user. Store messages too, so the ones that miss live delivery are fetched on reconnect."},
 see([(10, 'Polling, server-sent events and WebSockets compared at system scale'),
      (218, 'The client side of the same connection: reconnecting and resuming in the browser'),
      (356, 'Admission control and load shedding protect gateways during reconnect storms')])))

